import React from 'react';
import ReactDOM from 'react-dom/client';
import { Provider } from 'react-redux';
import store from './store';
import 'bootstrap/dist/css/bootstrap.min.css';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';

// Устанавливаем фон сразу при загрузке
if (typeof document !== 'undefined') {
  const html = document.documentElement;
  const body = document.body;
  
  // Устанавливаем тему по умолчанию
  const savedTheme = localStorage.getItem('theme');
  const theme = savedTheme || 'dark';
  html.setAttribute('data-theme', theme);
  body.setAttribute('data-theme', theme);
  
  html.style.background = 'transparent';
  html.style.backgroundColor = theme === 'light' ? '#f5f7fb' : '#050816';
  html.style.height = 'auto';
  html.style.width = '100%';
  html.style.minHeight = '100vh';
  body.style.background = 'transparent';
  
  // Создаем элемент для фона, если его еще нет
  let bgElement = document.getElementById('background-gradient');
  if (!bgElement) {
    bgElement = document.createElement('div');
    bgElement.id = 'background-gradient';
    document.body.insertBefore(bgElement, document.body.firstChild);
  }
  
  // Функция для обновления высоты фона
  const updateBackgroundHeight = () => {
    const docHeight = Math.max(
      document.body.scrollHeight,
      document.body.offsetHeight,
      document.documentElement.clientHeight,
      document.documentElement.scrollHeight,
      document.documentElement.offsetHeight
    );
    bgElement.style.height = `${docHeight}px`;
  };
  
  // Обновляем высоту при загрузке и изменении размера
  updateBackgroundHeight();
  window.addEventListener('resize', updateBackgroundHeight);
  window.addEventListener('scroll', updateBackgroundHeight);
  
  // Используем MutationObserver для отслеживания изменений DOM
  const observer = new MutationObserver(() => {
    setTimeout(updateBackgroundHeight, 0);
  });
  observer.observe(document.body, { childList: true, subtree: true });
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <Provider store={store}>
      <App />
    </Provider>
  </React.StrictMode>
);

// If you want to start measuring performance in your app, pass a function
// to log results (for example: reportWebVitals(console.log))
// or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals
reportWebVitals();

if ('serviceWorker' in navigator && process.env.NODE_ENV === 'production') {
  window.addEventListener('load', () => {
    navigator.serviceWorker
      .register(`${process.env.PUBLIC_URL}/service-worker.js`)
      .catch((error) => {
        console.error('Service worker registration failed:', error);
      });
  });
}
