import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { HashRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { authApi } from './api/authApi';
import { ThemeProvider } from './components/ThemeProvider';
import Header from './components/Header/Header';
import LoginPage from './pages/Auth/LoginPage';
import StudyPlanPage from './pages/Study/StudyPlanPage';
import SubjectPage from './pages/Study/SubjectPage';
import SchedulePage from './pages/Schedule/SchedulePage';
import NotificationsPage from './pages/Notifications/NotificationsPage';
import EduSusuPage from './pages/EduSusu/EduSusuPage';
import { Spinner } from 'react-bootstrap';
import { loginSuccess } from './store/slices/authSlice';
import changelog from './changelog.json';

// Компонент для обновления высоты страницы при изменении маршрута
const RouteHeightUpdater = () => {
    const location = useLocation();

    useEffect(() => {
        // Функция для обновления высоты страницы
        const updatePageHeight = () => {
            const bgElement = document.getElementById('background-gradient');
            if (bgElement) {
                // Принудительно пересчитываем высоту
                const docHeight = Math.max(
                    document.body.scrollHeight,
                    document.body.offsetHeight,
                    document.documentElement.clientHeight,
                    document.documentElement.scrollHeight,
                    document.documentElement.offsetHeight
                );
                bgElement.style.height = `${docHeight}px`;
            }
        };

        // Сбрасываем прокрутку при изменении маршрута
        window.scrollTo(0, 0);
        
        // Сначала сбрасываем высоту фона, чтобы убрать старое значение
        const bgElement = document.getElementById('background-gradient');
        if (bgElement) {
            bgElement.style.height = 'auto';
        }
        
        // Обновляем высоту через requestAnimationFrame для обновления после рендера
        const rafId = requestAnimationFrame(() => {
            updatePageHeight();
        });

        return () => {
            if (rafId) cancelAnimationFrame(rafId);
        };
    }, [location.pathname]);

    return null;
};

// Компонент для защищенных маршрутов с Header
const ProtectedRoute = ({ children, showChangelog, setShowChangelog }) => {
    const isAuthenticated = useSelector(state => state.auth.isAuthenticated);
    
    if (!isAuthenticated) {
        return <Navigate to="/login" replace />;
    }

    return (
        <>
            <Header showChangelog={showChangelog} setShowChangelog={setShowChangelog}/>
            {children}
        </>
    );
};

function App() {
    const [isChecking, setIsChecking] = useState(true);
    const [showChangelog, setShowChangelog] = useState(false);
    const isAuthenticated = useSelector(state => state.auth.isAuthenticated);
    const dispatch = useDispatch();

    useEffect(() => {
        const checkSession = async () => {
            try {
                const token = localStorage.getItem('authToken');
                const userData = localStorage.getItem('userData');

                if (token && userData) {
                    const isValid = await authApi.checkAuth();
                    if (isValid) {
                        // Восстанавливаем сессию: важно передать accessToken, иначе редьюсер не увидит токен
                        dispatch(loginSuccess({ accessToken: token, ...JSON.parse(userData) }));
                    }
                }
            } finally {
                setIsChecking(false);
            }
        };
        checkSession();
    }, [dispatch]);

    // Показываем список изменений только авторизованным пользователям и один раз на версию
    useEffect(() => {
        if (!isChecking && isAuthenticated && changelog?.version) {
            const lastSeen = localStorage.getItem('lastSeenChangelogVersion');
            if (lastSeen !== changelog.version) {
                setShowChangelog(true);
            }
        }
    }, [isChecking, isAuthenticated]);

    const handleCloseChangelog = () => {
        if (changelog?.version) {
            localStorage.setItem('lastSeenChangelogVersion', changelog.version);
        }
        setShowChangelog(false);
    };

    if (isChecking) {
        return (
            <div className="d-flex justify-content-center align-items-center" style={{ height: '100vh' }}>
                <Spinner animation="border" role="status">
                    <span className="visually-hidden">Loading...</span>
                </Spinner>
            </div>
        );
    }

    return (
        <ThemeProvider>
            <Router>
                <RouteHeightUpdater />
                <Routes>
                    <Route 
                        path="/login" 
                        element={isAuthenticated ? <Navigate to="/" replace /> : <LoginPage />} 
                    />
                    <Route 
                        path="/" 
                        element={
                            <ProtectedRoute showChangelog={showChangelog} setShowChangelog={setShowChangelog}>
                                <StudyPlanPage />
                            </ProtectedRoute>
                        } 
                    />
                    <Route 
                        path="/subject/:subjectId/:termNumber" 
                        element={
                            <ProtectedRoute>
                                <SubjectPage />
                            </ProtectedRoute>
                        } 
                    />
                    <Route 
                        path="/schedule" 
                        element={
                            <ProtectedRoute showChangelog={showChangelog} setShowChangelog={setShowChangelog}>
                                <SchedulePage />
                            </ProtectedRoute>
                        } 
                    />
                    <Route 
                        path="/notifications" 
                        element={
                            <ProtectedRoute showChangelog={showChangelog} setShowChangelog={setShowChangelog}>
                                <NotificationsPage />
                            </ProtectedRoute>
                        } 
                    />
                    <Route 
                        path="/edususu" 
                        element={
                            <ProtectedRoute showChangelog={showChangelog} setShowChangelog={setShowChangelog}>
                                <EduSusuPage />
                            </ProtectedRoute>
                        } 
                    />
                    <Route path="*" element={<Navigate to="/" replace />} />
                </Routes>
            </Router>
            {showChangelog && (
                <div className="changelog-backdrop">
                    <div className="changelog-modal">
                        <div className="changelog-header">
                            <h5 className="changelog-title">
                                {changelog.title || 'Что нового'}&nbsp;
                                {changelog.version && (
                                    <span className="changelog-version">v{changelog.version}</span>
                                )}
                            </h5>
                        </div>
                        <div className="changelog-body">
                            {Array.isArray(changelog.items) && changelog.items.length > 0 ? (
                                <ul className="changelog-list">
                                    {changelog.items.map((item, index) => {
                                        // Проверяем, является ли строка разделителем (только дефисы/тире/пробелы)
                                        const isSeparator = /^[\s\-–—]+$/.test(item);
                                        // Проверяем, является ли строка подпунктом (начинается с "- " или "— ")
                                        const isSubItem = /^[\-–—]\s/.test(item);
                                        const itemText = isSubItem ? item.replace(/^[\-–—]\s+/, '') : (isSeparator ? '' : item);
                                        
                                        return (
                                            <li 
                                                key={index} 
                                                className={`changelog-item ${isSeparator ? 'separator' : ''} ${isSubItem ? 'sub-item' : ''}`}
                                            >
                                                {!isSeparator && <span className="changelog-bullet" />}
                                                <span className="changelog-text">{itemText}</span>
                                            </li>
                                        );
                                    })}
                                </ul>
                            ) : (
                                <p className="mb-0">В этой версии нет явных изменений.</p>
                            )}
                        </div>
                        <div className="changelog-footer">
                            <button
                                type="button"
                                className="btn btn-primary w-100"
                                onClick={handleCloseChangelog}
                            >
                                Понятно...
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </ThemeProvider>
    );
}

export default App;
