import React from 'react';
import { Badge } from 'react-bootstrap';
import { getControlTypeBadgeClass, getRatingColor } from './subjectViewUtils';

const dotColors = {
    red: {
        background: 'radial-gradient(circle at 30% 30%, #fa1515ff, #ea0808ff)',
        boxShadow: '0 0 12px rgba(250, 21, 21, 0.8)'
    },
    yellow: {
        background: 'radial-gradient(circle at 30% 30%, #facc15, #eab308)',
        boxShadow: '0 0 12px rgba(250, 204, 21, 0.8)'
    },
    blue: {
        background: 'radial-gradient(circle at 30% 30%, #1915faff, #0817eaff)',
        boxShadow: '0 0 12px rgba(25, 21, 250, 0.8)'
    },
    green: {
        background: 'radial-gradient(circle at 30% 30%, #15fa20ff, #08ea13ff)',
        boxShadow: '0 0 12px rgba(21, 250, 21, 0.8)'
    }
};

const getDotColor = (rating, controlType) => {
    if (!rating && rating !== 0) return 'secondary';

    const typeRaw = (controlType || 'экзамен').toString().toLowerCase();

    if (typeRaw === 'зачет' || typeRaw === 'дифференцированный зачет') {
        return rating >= 59.01 ? dotColors.green : dotColors.red;
    }

    if (typeRaw === 'экзамен' || typeRaw === 'курсовые работы') {
        if (rating < 59.01) return dotColors.red;
        if (rating < 74.01) return dotColors.yellow;
        if (rating < 84.01) return dotColors.blue;
        return dotColors.green;
    }

    return dotColors.green;
};

function SubjectStickySummaryBar({ isDark, controlType, finalFactRating, finalPredictedRating }) {
    const factColorObj = getDotColor(finalFactRating, controlType);
    const predColorObj = getDotColor(finalPredictedRating, controlType);

    return (
        <div className={`sticky-summary-bar${isDark ? ' summary-bar-dark' : ''}`}>
            <div className="sticky-summary-bar-inner">
                <div className="summary-bar-left">
                    <div className="summary-bar-label-row">
                        <span className="summary-bar-dot" style={factColorObj} aria-hidden="true" />
                        <span className="summary-bar-label">Итоговый рейтинг</span>
                        <span className="summary-bar-dot" style={predColorObj} aria-hidden="true" />
                    </div>
                </div>
                <div className="summary-bar-values">
                    <Badge
                        bg={getRatingColor(finalFactRating, controlType)}
                        className={getControlTypeBadgeClass(controlType)}
                    >
                        {`Факт: ${finalFactRating.toFixed(2)}%`}
                    </Badge>
                    <Badge
                        bg={getRatingColor(finalPredictedRating, controlType)}
                        className={getControlTypeBadgeClass(controlType)}
                    >
                        {`Пред: ${finalPredictedRating.toFixed(2)}%`}
                    </Badge>
                </div>
            </div>
        </div>
    );
}

export default SubjectStickySummaryBar;


