import React from 'react';
import { Button, Badge, Alert, Form } from 'react-bootstrap';
import { getControlTypeBadgeClass } from './subjectViewUtils';

function SubjectHeader({
    loading,
    subjectData,
    termNumber,
    controlType,
    subjectId,
    error,
    canSetAgreement,
    isAgreed,
    onAgreementChange,
    onBack
}) {
    return (
        <>
            <div className="subject-page-header-row">
                <div className="subject-header-main">
                    <Button
                        variant="outline-secondary"
                        className="icon-btn subject-back-btn"
                        onClick={onBack}
                    >
                        <span aria-hidden="true">←</span>
                        <span className="d-none d-sm-inline">Назад</span>
                    </Button>

                    <div className="subject-title-block">
                        {loading ? (
                            <div className="subject-title-skeleton" />
                        ) : (
                            <h1 className="subject-title">
                                {subjectData?.disciplineName || 'Предмет'}
                            </h1>
                        )}
                        {!loading && subjectData && (
                            <p className="subject-subtitle">
                                Семестр {termNumber}
                                {controlType && (
                                    <>
                                        <Badge className={getControlTypeBadgeClass(controlType)}>
                                            {controlType}
                                        </Badge>
                                        {(subjectData?.id || subjectId) && (
                                            <a
                                                href={`https://studlk.susu.ru/ru/StudyPlan/OpenJournal/${subjectData?.id || subjectId}`}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="subject-pill subject-univeris-pill"
                                            >
                                                Универис
                                            </a>
                                        )}
                                    </>
                                )}
                            </p>
                        )}
                    </div>
                </div>
            </div>

            {error && (
                <Alert variant="danger" className="subject-alert">
                    {error}
                </Alert>
            )}

            {!loading && !error && !subjectData && (
                <Alert variant="warning" className="subject-alert">
                    Данные по предмету не найдены
                </Alert>
            )}

            {canSetAgreement && subjectData && (
                <div className="subject-agreement-block">
                    {subjectData.hasAgreement && (
                        <Badge bg="primary" className="subject-agreement-badge">
                            Рейтинг на момент согласия:{' '}
                            {subjectData.agreementRating.toFixed(2)}
                        </Badge>
                    )}
                    <Form.Check
                        type="checkbox"
                        id="agreement-checkbox"
                        label="Согласен с оценкой"
                        checked={isAgreed}
                        onChange={onAgreementChange}
                        disabled={!canSetAgreement}
                        className="subject-agreement-toggle"
                    />
                </div>
            )}
        </>
    );
}

export default SubjectHeader;


