import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Card, Alert, Badge, Button, ButtonGroup } from 'react-bootstrap';
import { useTheme } from '../ThemeProvider';
import { scheduleApi } from '../../api/scheduleApi';
import { studyApi } from '../../api/studyApi';
import { useSelector, useDispatch } from 'react-redux';
import { logout } from '../../store/slices/authSlice';
import { useNavigate } from 'react-router-dom';
import './Schedule.css';
import useResponsiveBreakpoint from '../../shared/hooks/useResponsiveBreakpoint';
import Loader from '../../shared/components/Loader';
import ErrorAlert from '../../shared/components/ErrorAlert';
import SessionCalendar from './SessionCalendar';

const Schedule = () => {
    const [schedule, setSchedule] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [currentWeekOffset, setCurrentWeekOffset] = useState(0);
    const [studyPlan, setStudyPlan] = useState(null);
    const [subjects, setSubjects] = useState([]);
    const [loadingSubjects, setLoadingSubjects] = useState(false);
    const [showCalendar, setShowCalendar] = useState(false);
    const isMobile = useResponsiveBreakpoint(520);
    const { isDark } = useTheme();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const { user } = useSelector((state) => state.auth);

    // Получаем groupId из user.student (может быть в разных полях)
    const groupId = user?.student?.groupId || user?.student?.group?.id || user?.student?.id;

    // Загружаем учебный план для получения текущего семестра
    useEffect(() => {
        const fetchStudyPlan = async () => {
            try {
                const planData = await studyApi.getStudyPlan();
                setStudyPlan(planData);
            } catch (err) {
                console.error('Error fetching study plan:', err);
            }
        };
        fetchStudyPlan();
    }, []);

    // Загружаем предметы для поиска по названию
    useEffect(() => {
        const fetchSubjects = async () => {
            if (!studyPlan?.currentTerm) return;
            try {
                setLoadingSubjects(true);
                const subjectsData = await studyApi.getSubjects(studyPlan.currentTerm);
                setSubjects(subjectsData || []);
            } catch (err) {
                console.error('Error fetching subjects:', err);
            } finally {
                setLoadingSubjects(false);
            }
        };
        fetchSubjects();
    }, [studyPlan]);

    useEffect(() => {
        const fetchSchedule = async () => {
            if (!groupId) {
                console.warn('GroupId not found in user data:', user?.student);
                setError('Не удалось определить группу. Пожалуйста, войдите снова.');
                setLoading(false);
                return;
            }

            try {
                setLoading(true);
                setError(null);
                const data = await scheduleApi.getGroupSchedule(groupId);
                setSchedule(data || []);
            } catch (err) {
                console.error('Error fetching schedule:', err);

                if (err.response?.status === 401) {
                    setError('Сессия истекла. Пожалуйста, войдите снова.');
                    dispatch(logout());
                } else {
                    setError(err.response?.data?.message || err.message || 'Ошибка при загрузке расписания');
                }
            } finally {
                setLoading(false);
            }
        };

        if (user) {
            fetchSchedule();
        }
    }, [groupId, dispatch, user]);

    // Получаем начало недели (понедельник) для даты
    const getWeekStart = (dateInput) => {
        const d = dateInput instanceof Date ? new Date(dateInput) : new Date(dateInput);
        const day = d.getDay();
        const diff = d.getDate() - day + (day === 0 ? -6 : 1); // Приводим к понедельнику
        const monday = new Date(d);
        monday.setDate(diff);
        monday.setHours(0, 0, 0, 0);
        return monday;
    };

    // Находим предмет по названию
    const findSubjectByName = (subjectName) => {
        if (!subjects || subjects.length === 0) return null;
        // Ищем точное совпадение или похожее название
        const found = subjects.find(subject => 
            subject.disciplineName?.toLowerCase() === subjectName?.toLowerCase() ||
            subjectName?.toLowerCase().includes(subject.disciplineName?.toLowerCase()) ||
            subject.disciplineName?.toLowerCase().includes(subjectName?.toLowerCase())
        );
        return found;
    };

    // Обработчик клика на предмет
    const handleSubjectClick = (subjectName) => {
        if (!studyPlan?.currentTerm) return;
        
        const subject = findSubjectByName(subjectName);
        if (subject && subject.disciplineId) {
            navigate(`/subject/${subject.disciplineId}/${studyPlan.currentTerm}`, {
                state: { controlType: subject.controlType }
            });
        }
    };

    // Группируем расписание по датам
    const groupByDate = (scheduleData) => {
        const grouped = {};
        scheduleData.forEach((item) => {
            const date = item.eventDate;
            if (!grouped[date]) {
                grouped[date] = [];
            }
            grouped[date].push(item);
        });

        // Сортируем занятия внутри каждого дня по времени начала
        Object.keys(grouped).forEach((date) => {
            grouped[date].sort((a, b) => {
                return a.beginTime.localeCompare(b.beginTime);
            });
        });

        // Сортируем даты
        return Object.keys(grouped)
            .sort()
            .reduce((result, date) => {
                result[date] = grouped[date];
                return result;
            }, {});
    };

    // Получаем все недели из расписания
    const getAllWeeks = useMemo(() => {
        if (!schedule || schedule.length === 0) return [];
        
        const weeksSet = new Set();
        schedule.forEach(item => {
            const weekStart = getWeekStart(item.eventDate);
            weeksSet.add(weekStart.toISOString().split('T')[0]);
        });
        
        return Array.from(weeksSet).sort();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [schedule]);

    // Получаем текущую неделю (неделю с сегодняшним днем)
    const getCurrentWeekStartDate = useMemo(() => {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        return getWeekStart(today).toISOString().split('T')[0];
    }, []);

    // Получаем индекс текущей недели в списке всех недель
    const getCurrentWeekIndex = useMemo(() => {
        if (getAllWeeks.length === 0) return -1;
        const index = getAllWeeks.findIndex(week => week === getCurrentWeekStartDate);
        return index;
    }, [getAllWeeks, getCurrentWeekStartDate]);

    // Получаем неделю для отображения
    const getCurrentWeekStart = useMemo(() => {
        // Если offset = 0, всегда показываем текущую неделю (даже если её нет в расписании)
        if (currentWeekOffset === 0 && getCurrentWeekStartDate) {
            return getCurrentWeekStartDate;
        }
        
        // Если текущая неделя найдена в расписании, используем её с учетом offset
        if (getCurrentWeekIndex >= 0) {
            const targetIndex = getCurrentWeekIndex + currentWeekOffset;
            if (targetIndex >= 0 && targetIndex < getAllWeeks.length) {
                return getAllWeeks[targetIndex];
            }
        }
        
        // Если offset != 0 и текущая неделя не найдена в расписании
        // Вычисляем неделю относительно текущей
        if (getCurrentWeekStartDate) {
            const currentWeekDate = new Date(getCurrentWeekStartDate);
            currentWeekDate.setDate(currentWeekDate.getDate() + (7 * currentWeekOffset));
            return currentWeekDate.toISOString().split('T')[0];
        }
        
        // Если нет текущей недели (маловероятно), показываем первую неделю из расписания
        if (getAllWeeks.length > 0) {
            return getAllWeeks[0];
        }
        
        return null;
    }, [getAllWeeks, getCurrentWeekIndex, currentWeekOffset, getCurrentWeekStartDate]);

    // Фильтруем расписание по текущей неделе
    const getWeekSchedule = useMemo(() => {
        if (!getCurrentWeekStart || !schedule.length) return {};
        
        const weekStartDate = new Date(getCurrentWeekStart);
        const weekEndDate = new Date(weekStartDate);
        weekEndDate.setDate(weekEndDate.getDate() + 6);
        weekEndDate.setHours(23, 59, 59, 999);
        
        const weekSchedule = schedule.filter(item => {
            const itemDate = new Date(item.eventDate);
            return itemDate >= weekStartDate && itemDate <= weekEndDate;
        });
        
        return groupByDate(weekSchedule);
    }, [schedule, getCurrentWeekStart]);

    // Форматируем диапазон дат недели
    const formatWeekRange = (weekStartStr) => {
        if (!weekStartStr) return '';
        const weekStart = new Date(weekStartStr);
        const weekEnd = new Date(weekStart);
        weekEnd.setDate(weekEnd.getDate() + 6);
        
        const monthNames = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 
                          'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
        
        const startDay = weekStart.getDate();
        const startMonth = monthNames[weekStart.getMonth()];
        const endDay = weekEnd.getDate();
        const endMonth = monthNames[weekEnd.getMonth()];
        
        if (weekStart.getMonth() === weekEnd.getMonth()) {
            return `${startDay} - ${endDay} ${startMonth}`;
        } else {
            return `${startDay} ${startMonth} - ${endDay} ${endMonth}`;
        }
    };

    // Сбрасываем на текущую неделю
    const goToCurrentWeek = () => {
        setCurrentWeekOffset(0);
    };

    // Автоматически скроллим к текущему дню при первой загрузке текущей недели
    const hasScrolledRef = useRef(false);
    useEffect(() => {
        if (!loading && getCurrentWeekStart && currentWeekOffset === 0 && !hasScrolledRef.current) {
            const today = new Date().toISOString().split('T')[0];
            const checkAndScroll = () => {
                const todayElement = document.querySelector(`[data-schedule-date="${today}"]`);
                if (todayElement) {
                    setTimeout(() => {
                        todayElement.scrollIntoView({ behavior: 'smooth', block: 'start' });
                        hasScrolledRef.current = true;
                    }, 200);
                } else {
                    // Если элемент еще не отрендерен, пробуем еще раз через небольшую задержку
                    setTimeout(checkAndScroll, 100);
                }
            };
            checkAndScroll();
        }
    }, [loading, getCurrentWeekStart, currentWeekOffset]);

    // Форматируем дату для отображения
    const formatDate = (dateString) => {
        const date = new Date(dateString);
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const tomorrow = new Date(today);
        tomorrow.setDate(tomorrow.getDate() + 1);

        const dateOnly = new Date(date);
        dateOnly.setHours(0, 0, 0, 0);

        const dayNames = ['Воскресенье', 'Понедельник', 'Вторник', 'Среда', 'Четверг', 'Пятница', 'Суббота'];
        const monthNames = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];

        const dayName = dayNames[date.getDay()];
        const day = date.getDate();
        const month = monthNames[date.getMonth()];

        if (dateOnly.getTime() === today.getTime()) {
            return `Сегодня, ${day} ${month}`;
        } else if (dateOnly.getTime() === tomorrow.getTime()) {
            return `Завтра, ${day} ${month}`;
        } else {
            return `${dayName}, ${day} ${month}`;
        }
    };

    // Форматируем время
    const formatTime = (timeString) => {
        return timeString.substring(0, 5); // Берем только часы и минуты
    };

    // Получаем короткое название типа занятия
    const getEventTypeShort = (eventTypeRaw) => {
        const eventType = eventTypeRaw || '';
        const type = eventType.toLowerCase();

        // Учебные занятия
        if (type.includes('лекц')) return 'Лекция';
        if (type.includes('практ') || type.includes('семинар')) return 'Практика';
        if (type.includes('лаборатор')) return 'Лабораторная';

        // Формы контроля
        if (type.includes('экзамен')) return 'Экзамен';
        if (type.includes('зачет') || type.includes('зачёт')) return 'Зачет';
        if (type.includes('консультация')) return 'Консультация';

        // Прочерк / пустое значение
        if (type.trim() === '-' || type.trim() === '—' || type.trim() === '') return '-';

        return eventType;
    };

    // Получаем класс для типа занятия
    const getEventTypeClass = (eventTypeRaw) => {
        const eventType = eventTypeRaw || '';
        const type = eventType.toLowerCase();

        // Учебные занятия
        if (type.includes('лекц')) return 'badge-event-lecture'; // Лекция / Лекции
        if (type.includes('практ') || type.includes('семинар')) return 'badge-event-practice'; // Практика / Семинар
        if (type.includes('лаборатор')) return 'badge-event-laboratory'; // Лабораторная

        // Формы контроля
        if (type.includes('экзамен')) return 'badge-control-exam'; // Экзамен
        if (type.includes('зачет') || type.includes('зачёт')) return 'badge-control-credit'; // Зачет
        if (type.includes('консультация')) return 'badge-control-consultation'; // Консультация к промежуточной аттестации

        // Прочерк / пустое значение
        if (type.trim() === '-' || type.trim() === '—' || type.trim() === '') return 'badge-control-empty';

        // Значение по умолчанию
        return 'badge-control-empty';
    };

    const renderContent = () => {
        if (loading) {
            return <Loader className="schedule-spinner" />;
        }

        if (error) {
            return <ErrorAlert message={error} className="schedule-alert" />;
        }

        if (schedule.length === 0) {
            return (
                <Alert variant="info" className="schedule-alert">
                    Нет данных о расписании
                </Alert>
            );
        }

        const groupedSchedule = getWeekSchedule;

        // Навигация по неделям: даём возможность свободно листать недели вперёд и назад.
        // Если для какой‑то недели нет данных, показываем сообщение "На этой неделе нет занятий".
        const hasPrevWeek = true;
        const hasNextWeek = true;

        const isCurrentWeek = currentWeekOffset === 0;

        return (
            <>
                <div className="schedule-week-navigation">
                    <ButtonGroup>
                        <Button
                            variant="outline-secondary"
                            size="sm"
                            onClick={() => setCurrentWeekOffset(prev => prev - 1)}
                            disabled={!hasPrevWeek}
                            className="schedule-nav-btn"
                        >
                            {isMobile ? '← Пред.' : '← Предыдущая'}
                        </Button>
                        <Button
                            variant={isCurrentWeek ? "primary" : "outline-secondary"}
                            size="sm"
                            onClick={goToCurrentWeek}
                            className="schedule-nav-btn"
                        >
                            {isMobile 
                                ? (isCurrentWeek ? 'Текущая' : 'К текущей')
                                : (isCurrentWeek ? 'Текущая неделя' : 'К текущей')
                            }
                        </Button>
                        <Button
                            variant="outline-secondary"
                            size="sm"
                            onClick={() => setCurrentWeekOffset(prev => prev + 1)}
                            disabled={!hasNextWeek}
                            className="schedule-nav-btn"
                        >
                            {isMobile ? 'След. →' : 'Следующая →'}
                        </Button>
                        <Button
                            variant="outline-secondary"
                            size="sm"
                            onClick={() => setShowCalendar(true)}
                            className="schedule-nav-btn"
                        >
                            {isMobile ? '📅 Календарь' : '📅 Календарь сессии'}
                        </Button>
                    </ButtonGroup>
                    {getCurrentWeekStart && (
                        <div className="schedule-week-range">
                            {formatWeekRange(getCurrentWeekStart)}
                        </div>
                    )}
                </div>
                <div className="schedule-content">
                    {Object.keys(groupedSchedule).length === 0 ? (
                        <Alert variant="info" className="schedule-alert">
                            На этой неделе нет занятий
                        </Alert>
                    ) : (
                        Object.entries(groupedSchedule).map(([date, events]) => {
                            const today = new Date().toISOString().split('T')[0];
                            const isToday = date === today;
                            return (
                                <div 
                                    key={date} 
                                    className={`schedule-day ${isToday ? 'schedule-day-today' : ''}`}
                                    data-schedule-date={date}
                                >
                                    <div className="schedule-day-header">
                                        <h4 className="schedule-day-title">{formatDate(date)}</h4>
                                    </div>
                                    <div className="schedule-events">
                                        {events.map((event, index) => {
                                            const subject = findSubjectByName(event.subject);
                                            const isClickable = subject && subject.disciplineId;
                                            return (
                                                <div 
                                                    key={index} 
                                                    className={`schedule-event ${isClickable ? 'schedule-event-clickable' : ''}`}
                                                    onClick={isClickable ? () => handleSubjectClick(event.subject) : undefined}
                                                    style={isClickable ? { cursor: 'pointer' } : {}}
                                                >
                                                    <div className="schedule-event-time">
                                                        <span className="schedule-time-start">{formatTime(event.beginTime)}</span>
                                                        <span className="schedule-time-separator">—</span>
                                                        <span className="schedule-time-end">{formatTime(event.endTime)}</span>
                                                    </div>
                                                    <div className="schedule-event-content">
                                                        <div className="schedule-event-header">
                                                            <h5 className="schedule-event-subject">{event.subject}</h5>
                                                            <Badge className={`schedule-event-type ${getEventTypeClass(event.eventType)}`}>
                                                                {getEventTypeShort(event.eventType)}
                                                            </Badge>
                                                        </div>
                                                        {event.instructors && event.instructors.length > 0 && (
                                                            <div className="schedule-event-details">
                                                                {event.instructors.map((instructor, idx) => (
                                                                    <div key={idx} className="schedule-instructor">
                                                                        <span className="schedule-instructor-name">{instructor.name}</span>
                                                                        {instructor.location && (
                                                                            <span className="schedule-location">{instructor.location}</span>
                                                                        )}
                                                                    </div>
                                                                ))}
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>
                            );
                        })
                    )}
                </div>
            </>
        );
    };

    return (
        <div className="page-wrapper schedule-page">
            <Card className="schedule-card card-modern">
                <Card.Header className="card-modern-header">
                    <div className="schedule-header">
                        <div className="schedule-title-block">
                            <h3 className="card-modern-title mb-1">Расписание</h3>
                            {user?.student?.groupName && (
                                <p className="schedule-subtitle">
                                    Группа: {user.student.groupName}
                                </p>
                            )}
                        </div>
                    </div>
                </Card.Header>
                <Card.Body className="schedule-body">
                    {renderContent()}
                </Card.Body>
            </Card>
            <SessionCalendar
                show={showCalendar}
                onHide={() => setShowCalendar(false)}
                schedule={schedule}
            />
        </div>
    );
};

export default Schedule;

