import React, { useMemo } from 'react';
import { Modal, Button, OverlayTrigger, Tooltip, Alert } from 'react-bootstrap';
import { useTheme } from '../ThemeProvider';
import { generateICSFile, downloadICSFile, isPWAInstalled } from '../../shared/lib/calendarExport';
import './SessionCalendar.css';

/**
 * Компонент календаря сессии
 * Подсвечивает красным: день до зачета, день промежуточной консультации
 * Подсвечивает синим: день зачета, день экзамена
 * @param {Object} props
 * @param {boolean} props.show - Показывать ли модальное окно
 * @param {Function} props.onHide - Функция для скрытия модального окна
 * @param {Array} props.schedule - Массив событий расписания
 */
function SessionCalendar({ show, onHide, schedule = [] }) {
    const { isDark } = useTheme();

    // Определяем даты для подсветки: красные и синие, с информацией о предметах
    const { redDates, blueDates } = useMemo(() => {
        const redDatesMap = new Map(); // date -> [{ subject, type }]
        const blueDatesMap = new Map(); // date -> [{ subject, type }]
        
        schedule.forEach((event) => {
            const eventType = (event.eventType || '').toLowerCase();
            const subject = event.subject || 'Неизвестный предмет';
            
            // Парсим дату в локальном времени, чтобы избежать проблем с часовыми поясами
            let eventDate;
            if (typeof event.eventDate === 'string') {
                // Если дата в формате YYYY-MM-DD, парсим локально
                const [year, month, day] = event.eventDate.split('-').map(Number);
                eventDate = new Date(year, month - 1, day);
            } else {
                eventDate = new Date(event.eventDate);
            }
            
            // Форматируем дату в YYYY-MM-DD в локальном времени
            const year = eventDate.getFullYear();
            const month = String(eventDate.getMonth() + 1).padStart(2, '0');
            const day = String(eventDate.getDate()).padStart(2, '0');
            const dateStr = `${year}-${month}-${day}`;
            
            const isConsultation = eventType.includes('консультация') || 
                                  eventType.includes('промежуточной аттестации');
            const isCredit = eventType.includes('зачет') || eventType.includes('зачёт');
            const isExam = eventType.includes('экзамен');
            
            if (isConsultation) {
                // Красный: день промежуточной консультации (сам день)
                if (!redDatesMap.has(dateStr)) {
                    redDatesMap.set(dateStr, []);
                }
                redDatesMap.get(dateStr).push({ subject, type: 'консультация' });
            } else if (isCredit) {
                // Синий: день зачета
                if (!blueDatesMap.has(dateStr)) {
                    blueDatesMap.set(dateStr, []);
                }
                blueDatesMap.get(dateStr).push({ subject, type: 'зачет' });
                
                // Красный: день до зачета
                const dayBefore = new Date(eventDate);
                dayBefore.setDate(dayBefore.getDate() - 1);
                const dayBeforeYear = dayBefore.getFullYear();
                const dayBeforeMonth = String(dayBefore.getMonth() + 1).padStart(2, '0');
                const dayBeforeDay = String(dayBefore.getDate()).padStart(2, '0');
                const dayBeforeStr = `${dayBeforeYear}-${dayBeforeMonth}-${dayBeforeDay}`;
                
                if (!redDatesMap.has(dayBeforeStr)) {
                    redDatesMap.set(dayBeforeStr, []);
                }
                redDatesMap.get(dayBeforeStr).push({ subject, type: 'зачет' });
            } else if (isExam) {
                // Синий: день экзамена
                if (!blueDatesMap.has(dateStr)) {
                    blueDatesMap.set(dateStr, []);
                }
                blueDatesMap.get(dateStr).push({ subject, type: 'экзамен' });
            }
        });
        
        return { redDates: redDatesMap, blueDates: blueDatesMap };
    }, [schedule]);

    // Форматируем дату в YYYY-MM-DD в локальном времени
    const formatDateLocal = (date) => {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    };

    // Получаем информацию о дате для тултипа
    const getDateInfo = (date) => {
        const dateStr = formatDateLocal(date);
        const redInfo = redDates.get(dateStr);
        const blueInfo = blueDates.get(dateStr);
        
        const items = [];
        
        if (redInfo && redInfo.length > 0) {
            // Красная дата - показываем информацию о согласии с оценкой
            const redItems = redInfo.map(item => `${item.subject} - согласие с оценкой`);
            items.push(...redItems);
        }
        
        if (blueInfo && blueInfo.length > 0) {
            // Синяя дата - показываем информацию о зачете/экзамене
            const blueItems = blueInfo.map(item => {
                const typeText = item.type === 'зачет' ? 'зачет' : 'экзамен';
                return `${item.subject} - ${typeText}`;
            });
            items.push(...blueItems);
        }
        
        if (items.length > 0) {
            const hasBoth = redInfo && redInfo.length > 0 && blueInfo && blueInfo.length > 0;
            return { 
                type: hasBoth ? 'both' : (redInfo && redInfo.length > 0 ? 'red' : 'blue'), 
                text: items.join('\n') 
            };
        }
        
        return null;
    };

    // Проверяем тип подсветки даты
    const getDateHighlightType = (date) => {
        const dateStr = formatDateLocal(date);
        const hasRed = redDates.has(dateStr);
        const hasBlue = blueDates.has(dateStr);
        
        // Если есть и красная, и синяя подсветка - возвращаем 'both'
        if (hasRed && hasBlue) return 'both';
        if (hasBlue) return 'blue';
        if (hasRed) return 'red';
        return null;
    };

    // Генерируем календарь для текущего месяца
    const generateCalendar = (year, month) => {
        const firstDay = new Date(year, month, 1);
        const lastDay = new Date(year, month + 1, 0);
        const daysInMonth = lastDay.getDate();
        const startingDayOfWeek = firstDay.getDay() === 0 ? 6 : firstDay.getDay() - 1; // Понедельник = 0

        const calendar = [];
        
        // Добавляем пустые ячейки для дней до начала месяца
        for (let i = 0; i < startingDayOfWeek; i++) {
            calendar.push(null);
        }
        
        // Добавляем дни месяца
        for (let day = 1; day <= daysInMonth; day++) {
            const date = new Date(year, month, day);
            calendar.push(date);
        }
        
        return calendar;
    };

    const today = new Date();
    const [currentMonth, setCurrentMonth] = React.useState(today.getMonth());
    const [currentYear, setCurrentYear] = React.useState(today.getFullYear());

    const calendar = useMemo(() => {
        return generateCalendar(currentYear, currentMonth);
    }, [currentYear, currentMonth]);

    const monthNames = [
        'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
        'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь'
    ];

    const dayNames = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];

    const goToPreviousMonth = () => {
        if (currentMonth === 0) {
            setCurrentMonth(11);
            setCurrentYear(currentYear - 1);
        } else {
            setCurrentMonth(currentMonth - 1);
        }
    };

    const goToNextMonth = () => {
        if (currentMonth === 11) {
            setCurrentMonth(0);
            setCurrentYear(currentYear + 1);
        } else {
            setCurrentMonth(currentMonth + 1);
        }
    };

    const goToToday = () => {
        setCurrentMonth(today.getMonth());
        setCurrentYear(today.getFullYear());
    };

    const isToday = (date) => {
        if (!date) return false;
        const todayStr = formatDateLocal(today);
        const dateStr = formatDateLocal(date);
        return todayStr === dateStr;
    };

    // Собираем все даты согласия с оценкой (красные даты) для экспорта
    const getAgreementDates = useMemo(() => {
        const agreementEvents = [];
        
        // Проходим по всем красным датам
        redDates.forEach((subjects, dateStr) => {
            // Для каждой даты создаем события для каждого предмета
            subjects.forEach(({ subject, type }) => {
                // Парсим дату из строки YYYY-MM-DD
                const [year, month, day] = dateStr.split('-').map(Number);
                const date = new Date(year, month - 1, day);
                
                // Определяем описание в зависимости от типа
                let description = '';
                if (type === 'консультация') {
                    description = 'День консультации - необходимо согласие с оценкой';
                } else if (type === 'зачет') {
                    description = 'День до зачета - необходимо согласие с оценкой';
                }
                
                agreementEvents.push({
                    subject: `${subject} - Согласие с оценкой`,
                    date,
                    description
                });
            });
        });
        
        return agreementEvents;
    }, [redDates]);

    // Обработчик экспорта календаря
    const handleExportCalendar = () => {
        if (getAgreementDates.length === 0) {
            alert('Нет дат для экспорта. Убедитесь, что в расписании есть события, требующие согласия с оценкой.');
            return;
        }

        try {
            const icsContent = generateICSFile(getAgreementDates, 'Согласие с оценкой - Сессия');
            const filename = `session-agreement-${new Date().toISOString().split('T')[0]}.ics`;
            downloadICSFile(icsContent, filename);
        } catch (error) {
            console.error('Ошибка при экспорте календаря:', error);
            alert('Произошла ошибка при экспорте календаря. Попробуйте еще раз.');
        }
    };

    return (
        <Modal
            show={show}
            onHide={onHide}
            centered
            size="md"
            className="session-calendar-modal"
            data-bs-theme={isDark ? 'dark' : 'light'}
        >
            <Modal.Header closeButton>
                <Modal.Title>Календарь сессии</Modal.Title>
            </Modal.Header>
            <Modal.Body>
                <div className="session-calendar-container">
                    <div className="session-calendar-header">
                        <Button
                            variant="outline-secondary"
                            size="sm"
                            onClick={goToPreviousMonth}
                            className="session-calendar-nav-btn"
                        >
                            ←
                        </Button>
                        <div className="session-calendar-month-year">
                            <span className="session-calendar-month">{monthNames[currentMonth]}</span>
                            <span className="session-calendar-year">{currentYear}</span>
                        </div>
                        <Button
                            variant="outline-secondary"
                            size="sm"
                            onClick={goToNextMonth}
                            className="session-calendar-nav-btn"
                        >
                            →
                        </Button>
                    </div>
                    <div className="session-calendar-today-btn-wrapper">
                        <Button
                            variant="outline-primary"
                            size="sm"
                            onClick={goToToday}
                            className="session-calendar-today-btn"
                        >
                            Сегодня
                        </Button>
                    </div>
                    <div className="session-calendar-grid">
                        {/* Заголовки дней недели */}
                        {dayNames.map((dayName, index) => (
                            <div key={index} className="session-calendar-day-header">
                                {dayName}
                            </div>
                        ))}
                        {/* Дни месяца */}
                        {calendar.map((date, index) => {
                            if (!date) {
                                return <div key={`empty-${index}`} className="session-calendar-day empty" />;
                            }
                            
                            const highlightType = getDateHighlightType(date);
                            const todayClass = isToday(date) ? 'today' : '';
                            const dateInfo = getDateInfo(date);
                            
                            const dayElement = (
                                <div
                                    key={date.toISOString()}
                                    className={`session-calendar-day ${highlightType ? `highlighted-${highlightType}` : ''} ${todayClass}`}
                                >
                                    <span className="session-calendar-day-number">
                                        {date.getDate()}
                                    </span>
                                </div>
                            );
                            
                            // Если есть информация для тултипа, оборачиваем в OverlayTrigger
                            if (dateInfo) {
                                return (
                                    <OverlayTrigger
                                        key={date.toISOString()}
                                        placement="top"
                                        overlay={
                                            <Tooltip>
                                                <div style={{ whiteSpace: 'pre-line', textAlign: 'left' }}>
                                                    {dateInfo.text}
                                                </div>
                                            </Tooltip>
                                        }
                                        delay={{ show: 300, hide: 100 }}
                                    >
                                        {dayElement}
                                    </OverlayTrigger>
                                );
                            }
                            
                            return dayElement;
                        })}
                    </div>
                    <div className="session-calendar-legend">
                        <div className="session-calendar-legend-item">
                            <div className="session-calendar-legend-color highlighted-red"></div>
                            <span>Согласие с оценкой</span>
                        </div>
                        <div className="session-calendar-legend-item">
                            <div className="session-calendar-legend-color highlighted-blue"></div>
                            <span>Зачет / Экзамен</span>
                        </div>
                        <div className="session-calendar-legend-item">
                            <div className="session-calendar-legend-color highlighted-both"></div>
                            <span>Зачет/экзамен + согласие с оценкой</span>
                        </div>
                    </div>
                </div>
            </Modal.Body>
            <Modal.Footer className="session-calendar-footer">
                <div className="session-calendar-footer-content">
                    <Button
                        variant="primary"
                        onClick={handleExportCalendar}
                        disabled={getAgreementDates.length === 0}
                        className="session-calendar-export-btn"
                    >
                        <span className="session-calendar-export-icon">📱</span>
                        <span>Выгрузить на телефон</span>
                    </Button>
                    <Button 
                        variant="secondary" 
                        onClick={onHide}
                        className="session-calendar-close-btn"
                    >
                        Закрыть
                    </Button>
                </div>
                {!isPWAInstalled() && getAgreementDates.length > 0 && (
                    <Alert variant="info" className="session-calendar-pwa-alert">
                        <small>
                            Для лучшей работы рекомендуется установить приложение как PWA. 
                            После скачивания файла откройте его на телефоне для добавления в календарь.
                        </small>
                    </Alert>
                )}
            </Modal.Footer>
        </Modal>
    );
}

export default SessionCalendar;

