import React from 'react';
import { Table, Badge, OverlayTrigger, Tooltip } from 'react-bootstrap';
import { getControlTypeBadgeClass, getRatingColor } from '../../../components/Study/subjectViewUtils';
import PredictionInput from '../../../shared/components/PredictionInput';

/**
 * Таблица для отображения текущего контроля или курсовых работ
 * @param {Object} props
 * @param {Array} props.items - Массив элементов (currentControl/labs или courseWorksOrProjects)
 * @param {Object} props.predictedRatings - Объект с предсказанными рейтингами { name: rating }
 * @param {string} props.predictionMode - Режим предсказания: 'percent' или 'points'
 * @param {string} props.controlType - Тип контроля
 * @param {Function} props.onPredictionChange - Коллбэк при изменении предсказания (name, value, maxPoint)
 * @param {Function} props.onQuickSet - Коллбэк для быстрой установки (name, value, maxPoint)
 */
function SubjectControlTable({
    items,
    predictedRatings,
    predictionMode,
    controlType,
    onPredictionChange,
    onQuickSet
}) {
    const isEdited = (item) => {
        return predictedRatings[item.name] !== undefined &&
            String(Number(predictedRatings[item.name]) ?? '') !== String(Number(item.rating) ?? '');
    };

    const handleChange = (name, value, maxPoint) => {
        if (value === '') {
            onPredictionChange(name, '', maxPoint);
            return;
        }

        let percentValue;
        if (predictionMode === 'points') {
            const points = Math.max(parseFloat(value) || 0, 0);
            const rawMax = parseFloat(maxPoint);
            const safeMax = Number.isFinite(rawMax) && rawMax > 0 ? rawMax : 100;
            percentValue = Math.min((points / safeMax) * 100, 100);
        } else {
            percentValue = Math.min(Math.max(parseFloat(value) || 0, 0), 100);
        }
        onPredictionChange(name, percentValue, maxPoint);
    };

    const handleQuickSet = (name, value, maxPoint) => {
        // PredictionInput передает проценты (0-100) напрямую
        // В режиме points нам нужно конвертировать проценты в баллы для передачи в quickSetPrediction
        if (predictionMode === 'points' && maxPoint) {
            // value уже в процентах, конвертируем в баллы
            const points = (value / 100) * maxPoint;
            onQuickSet(name, points, maxPoint);
        } else {
            // В режиме percent value уже в процентах
            onQuickSet(name, value, maxPoint);
        }
    };

    return (
        <div className="table-responsive subject-table-wrap">
            <Table hover responsive size="sm" className="subject-table">
                <thead>
                    <tr>
                        <th>Название</th>
                        <th>Рейтинг</th>
                        <th>
                            <OverlayTrigger
                                placement="top"
                                overlay={<Tooltip>Баллы</Tooltip>}
                                delay={{ show: 0, hide: 250 }}
                                trigger={['hover', 'focus', 'click']}
                            >
                                <div>
                                    <span className="d-none d-sm-inline">Баллы</span>
                                    <span className="d-inline d-sm-none">Б</span>
                                </div>
                            </OverlayTrigger>
                        </th>
                        <th>
                            <OverlayTrigger
                                placement="top"
                                overlay={<Tooltip>Максимальные баллы</Tooltip>}
                                delay={{ show: 0, hide: 250 }}
                                trigger={['hover', 'focus', 'click']}
                            >
                                <div>
                                    <span className="d-none d-sm-inline">Макс. баллы</span>
                                    <span className="d-inline d-sm-none">МБ</span>
                                </div>
                            </OverlayTrigger>
                        </th>
                        <th>
                            <OverlayTrigger
                                placement="top"
                                overlay={<Tooltip>Вес</Tooltip>}
                                delay={{ show: 0, hide: 250 }}
                                trigger={['hover', 'focus', 'click']}
                            >
                                <div>
                                    <span className="d-none d-sm-inline">Вес</span>
                                    <span className="d-inline d-sm-none">В</span>
                                </div>
                            </OverlayTrigger>
                        </th>
                        <th>
                            <OverlayTrigger
                                placement="top"
                                overlay={<Tooltip>Предсказание</Tooltip>}
                                delay={{ show: 0, hide: 250 }}
                                trigger={['hover', 'focus', 'click']}
                            >
                                <div>
                                    <span className="d-none d-sm-inline">Предсказание</span>
                                    <span className="d-inline d-sm-none">Пред.</span>
                                </div>
                            </OverlayTrigger>
                        </th>
                    </tr>
                </thead>
                <tbody>
                    {items.map((item, index) => (
                        <tr key={index} className={isEdited(item) ? 'row-edited' : ''}>
                            <td>{item.name}</td>
                            <td>
                                <Badge
                                    bg={getRatingColor(item.rating, controlType)}
                                    className={getControlTypeBadgeClass(controlType)}
                                >
                                    {item.rating.toFixed(2)}
                                </Badge>
                            </td>
                            <td>{item.point}</td>
                            <td>{item.maxPoint}</td>
                            <td>{item.weight}</td>
                            <td>
                                <PredictionInput
                                    mode={predictionMode}
                                    value={predictedRatings[item.name] ?? ''}
                                    maxPoint={item.maxPoint}
                                    onChange={(value) => handleChange(item.name, value, item.maxPoint)}
                                    onQuickSet={(value) => handleQuickSet(item.name, value, item.maxPoint)}
                                />
                            </td>
                        </tr>
                    ))}
                </tbody>
            </Table>
        </div>
    );
}

export default SubjectControlTable;

