import React from 'react';
import { Modal, Button } from 'react-bootstrap';
import { QRCodeSVG } from 'qrcode.react';
import { useTheme } from '../../components/ThemeProvider';
import './QROverlay.css';

/**
 * Компонент для отображения QR кода поверх экрана
 * @param {Object} props
 * @param {boolean} props.show - Показывать ли overlay
 * @param {Function} props.onHide - Функция для скрытия overlay
 * @param {string|number} props.value - Значение для QR кода
 * @param {string} [props.title] - Заголовок модального окна
 */
function QROverlay({ show, onHide, value, title = 'Пропуск' }) {
    const { isDark } = useTheme();
    
    if (!value) {
        return null;
    }
    
    // Преобразуем значение в строку для QR кода
    const qrValue = String(value);
    
    return (
        <Modal
            show={show}
            onHide={onHide}
            centered
            size="sm"
            className="qr-overlay-modal"
            data-bs-theme={isDark ? 'dark' : 'light'}
        >
            <Modal.Header closeButton>
                <Modal.Title>{title}</Modal.Title>
            </Modal.Header>
            <Modal.Body className="text-center">
                <div className="qr-code-container">
                    <QRCodeSVG
                        value={qrValue}
                        size={256}
                        level="H"
                        includeMargin={true}
                    />
                </div>
                <div className="mt-3">
                    <p className="text-muted mb-0">Номер пропуска: <strong>{qrValue}</strong></p>
                </div>
            </Modal.Body>
            <Modal.Footer>
                <Button variant="secondary" onClick={onHide}>
                    Закрыть
                </Button>
            </Modal.Footer>
        </Modal>
    );
}

export default QROverlay;

