/**
 * Утилита для экспорта событий календаря в формат iCalendar (.ics)
 */

/**
 * Форматирует дату в формат iCalendar (YYYYMMDDTHHmmssZ) для даты-времени в UTC
 * @param {Date} date - Дата для форматирования
 * @returns {string} Отформатированная дата
 */
function formatICalDateTime(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const seconds = String(date.getSeconds()).padStart(2, '0');
    return `${year}${month}${day}T${hours}${minutes}${seconds}Z`;
}

/**
 * Форматирует дату в формат iCalendar (YYYYMMDDTHHmmss) для локального времени
 * @param {Date} date - Дата для форматирования
 * @returns {string} Отформатированная дата без Z (локальное время)
 */
function formatICalLocalDateTime(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const seconds = String(date.getSeconds()).padStart(2, '0');
    return `${year}${month}${day}T${hours}${minutes}${seconds}`;
}

/**
 * Форматирует дату в формат iCalendar (YYYYMMDD) для событий на весь день
 * @param {Date} date - Дата для форматирования
 * @returns {string} Отформатированная дата
 */
function formatICalDate(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}${month}${day}`;
}

/**
 * Экранирует специальные символы для iCalendar формата
 * @param {string} text - Текст для экранирования
 * @returns {string} Экранированный текст
 */
function escapeICalText(text) {
    if (!text) return '';
    return text
        .replace(/\\/g, '\\\\')
        .replace(/;/g, '\\;')
        .replace(/,/g, '\\,')
        .replace(/\n/g, '\\n');
}

/**
 * Генерирует уникальный идентификатор для события
 * @param {string} subject - Название предмета
 * @param {string} date - Дата события
 * @returns {string} Уникальный идентификатор
 */
function generateUID(subject, date) {
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 9);
    return `${timestamp}-${random}-${subject}-${date}@univeris.app`;
}

/**
 * Создает событие календаря в формате iCalendar
 * @param {Object} event - Объект события
 * @param {string} event.subject - Название предмета
 * @param {Date} event.date - Дата события
 * @param {string} event.description - Описание события
 * @returns {string} Строка события в формате iCalendar
 */
function createICalEvent({ subject, date, description = '' }) {
    // Используем формат даты-времени для отображения времени 00:00:00 - 23:59:59
    // Начало события - текущий день в 00:00:00
    const startDate = new Date(date);
    startDate.setHours(0, 0, 0, 0);
    
    // Конец события - тот же день в 23:59:59
    const endDate = new Date(date);
    endDate.setHours(23, 59, 59, 0);
    
    // Напоминание на 12:00 локального времени
    const alarmDate = new Date(date);
    alarmDate.setHours(12, 0, 0, 0);
    
    const uid = generateUID(subject, date.toISOString().split('T')[0]);
    const now = new Date();
    
    const icalEvent = [
        'BEGIN:VEVENT',
        `UID:${uid}`,
        `DTSTAMP:${formatICalDateTime(now)}`,
        `DTSTART:${formatICalLocalDateTime(startDate)}`,
        `DTEND:${formatICalLocalDateTime(endDate)}`,
        `SUMMARY:${escapeICalText(subject)}`,
        description ? `DESCRIPTION:${escapeICalText(description)}` : '',
        'STATUS:CONFIRMED',
        'SEQUENCE:0',
        'BEGIN:VALARM',
        'ACTION:DISPLAY',
        `TRIGGER;VALUE=DATE-TIME:${formatICalLocalDateTime(alarmDate)}`,
        `DESCRIPTION:${escapeICalText(subject)}`,
        'END:VALARM',
        'END:VEVENT'
    ].filter(line => line !== '').join('\r\n');
    
    return icalEvent;
}

/**
 * Генерирует полный .ics файл из массива событий
 * @param {Array<Object>} events - Массив событий
 * @param {string} calendarName - Название календаря
 * @returns {string} Содержимое .ics файла
 */
export function generateICSFile(events, calendarName = 'Календарь сессии') {
    const header = [
        'BEGIN:VCALENDAR',
        'VERSION:2.0',
        'PRODID:-//Univeris//Calendar Export//RU',
        `X-WR-CALNAME:${escapeICalText(calendarName)}`,
        'CALSCALE:GREGORIAN',
        'METHOD:PUBLISH'
    ].join('\r\n');
    
    const icalEvents = events.map(event => createICalEvent(event)).join('\r\n');
    
    const footer = 'END:VCALENDAR';
    
    return `${header}\r\n${icalEvents}\r\n${footer}`;
}

/**
 * Скачивает .ics файл
 * @param {string} icsContent - Содержимое .ics файла
 * @param {string} filename - Имя файла
 */
export function downloadICSFile(icsContent, filename = 'session-calendar.ics') {
    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
}

/**
 * Проверяет, установлено ли приложение как PWA
 * @returns {boolean} true, если приложение установлено как PWA
 */
export function isPWAInstalled() {
    // Проверка для различных платформ
    if (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) {
        return true;
    }
    // Проверка для iOS
    if (window.navigator.standalone === true) {
        return true;
    }
    // Проверка для Android Chrome
    if (window.matchMedia && window.matchMedia('(display-mode: fullscreen)').matches) {
        return true;
    }
    return false;
}

