import React from 'react';
import { Badge } from 'react-bootstrap';
import './RemainingClassesInfo.css';

/**
 * Компонент для отображения информации об оставшихся занятиях
 */
const RemainingClassesInfo = ({ remainingClasses, loading = false }) => {
    if (loading) {
        return (
            <div className="remaining-classes-info">
                <span className="remaining-classes-label">Занятия:</span>
                <span className="remaining-classes-loading">Загрузка...</span>
            </div>
        );
    }

    if (!remainingClasses || remainingClasses.total === 0) {
        return null;
    }

    const hasAnyClasses = remainingClasses.lectures > 0 || 
                         remainingClasses.practices > 0 || 
                         remainingClasses.laboratories > 0;

    if (!hasAnyClasses) {
        return null;
    }

    return (
        <div className="remaining-classes-info">
            <span className="remaining-classes-label">Осталось занятий:</span>
            <div className="remaining-classes-badges">
                {remainingClasses.lectures > 0 && (
                    <Badge className="remaining-classes-badge remaining-classes-badge-lecture">
                        {remainingClasses.lectures} {remainingClasses.lectures === 1 ? 'лекция' : 
                         remainingClasses.lectures < 5 ? 'лекции' : 'лекций'}
                    </Badge>
                )}
                {remainingClasses.practices > 0 && (
                    <Badge className="remaining-classes-badge remaining-classes-badge-practice">
                        {remainingClasses.practices} {remainingClasses.practices === 1 ? 'практика' : 
                         remainingClasses.practices < 5 ? 'практики' : 'практик'}
                    </Badge>
                )}
                {remainingClasses.laboratories > 0 && (
                    <Badge className="remaining-classes-badge remaining-classes-badge-laboratory">
                        {remainingClasses.laboratories} {remainingClasses.laboratories === 1 ? 'лабораторная' : 
                         remainingClasses.laboratories < 5 ? 'лабораторные' : 'лабораторных'}
                    </Badge>
                )}
            </div>
        </div>
    );
};

export default RemainingClassesInfo;

