import React, { useState, useEffect } from 'react';
import { Dropdown, Badge, Spinner } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { notificationsApi } from '../../api/notificationsApi';
import './NotificationsDropdown.css';

/**
 * Компонент выпадающего меню уведомлений
 * @param {Object} props
 * @param {number} props.unreadCount - Количество непрочитанных уведомлений (для badge)
 * @param {Function} props.onNotificationsUpdate - Коллбэк для обновления количества непрочитанных
 */
function NotificationsDropdown({ unreadCount = 0, onNotificationsUpdate }) {
    const [notifications, setNotifications] = useState([]);
    const [loading, setLoading] = useState(false);
    const [show, setShow] = useState(false);
    const navigate = useNavigate();

    const loadNotifications = async () => {
        try {
            setLoading(true);
            const data = await notificationsApi.getUserNotifications();
            setNotifications(data || []);
            
            // Обновляем количество непрочитанных
            const unread = (data || []).filter(n => !n.IsRead).length;
            if (onNotificationsUpdate) {
                onNotificationsUpdate(unread);
            }
            return data || [];
        } catch (error) {
            console.error('Error loading notifications:', error);
            return [];
        } finally {
            setLoading(false);
        }
    };

    // Помечаем все непрочитанные уведомления как прочитанные
    const markAllAsRead = async (notificationsToMark) => {
        const unreadNotifications = notificationsToMark.filter(n => !n.IsRead);
        
        if (unreadNotifications.length === 0) {
            return;
        }
        
        // Помечаем все непрочитанные уведомления как прочитанные параллельно
        const markPromises = unreadNotifications.map(notification =>
            notificationsApi.setNotificationAsRead(notification.Id).catch(err => {
                console.error(`Error marking notification ${notification.Id} as read:`, err);
                return null; // Продолжаем даже если одно уведомление не удалось пометить
            })
        );
        
        await Promise.all(markPromises);
        
        // Обновляем локальное состояние
        const updatedNotifications = notificationsToMark.map(n => ({
            ...n,
            IsRead: true
        }));
        setNotifications(updatedNotifications);
        
        // Обновляем счетчик непрочитанных
        if (onNotificationsUpdate) {
            onNotificationsUpdate(0);
        }
    };

    // Загружаем уведомления при открытии меню и помечаем их как прочитанные
    useEffect(() => {
        if (show) {
            loadNotifications().then((loadedNotifications) => {
                // После загрузки помечаем все непрочитанные как прочитанные
                if (loadedNotifications && loadedNotifications.length > 0) {
                    markAllAsRead(loadedNotifications);
                }
            });
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [show]);

    // Загружаем уведомления при монтировании для подсчета непрочитанных
    useEffect(() => {
        loadNotifications();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const handleShow = () => {
        setShow(true);
    };

    const handleHide = () => {
        setShow(false);
    };

    const handleViewAll = () => {
        setShow(false);
        navigate('/notifications');
    };

    const formatDate = (dateString) => {
        // Дата приходит в формате "21:07:12 27.11.2025"
        return dateString || '';
    };

    const displayNotifications = notifications.slice(0, 5); // Показываем только первые 5

    return (
        <Dropdown 
            show={show} 
            onToggle={(isOpen) => isOpen ? handleShow() : handleHide()}
            className="notifications-dropdown"
        >
            <Dropdown.Toggle 
                variant="outline-primary"
                className="icon-btn header-action-btn notifications-btn"
                id="notifications-dropdown-toggle"
            >
                <span className="notifications-icon-wrapper">
                    <span className="notifications-icon">
                        <svg 
                            width="20" 
                            height="20" 
                            viewBox="0 0 24 24" 
                            fill="none" 
                            stroke="currentColor" 
                            strokeWidth="2" 
                            strokeLinecap="round" 
                            strokeLinejoin="round"
                        >
                            <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"></path>
                            <path d="M13.73 21a2 2 0 0 1-3.46 0"></path>
                        </svg>
                    </span>
                    {unreadCount > 0 && (
                        <Badge 
                            bg="danger" 
                            className="notifications-badge"
                            pill
                        >
                            {unreadCount > 99 ? '99+' : unreadCount}
                        </Badge>
                    )}
                </span>
            </Dropdown.Toggle>

            <Dropdown.Menu 
                className="notifications-menu"
                align="end"
            >
                <div className="notifications-header">
                    <h6 className="notifications-title">Уведомления</h6>
                    {unreadCount > 0 && (
                        <Badge bg="primary" className="notifications-header-badge">
                            {unreadCount} непрочитанных
                        </Badge>
                    )}
                </div>

                <div className="notifications-list">
                    {loading ? (
                        <div className="notifications-loading">
                            <Spinner animation="border" size="sm" />
                            <span className="ms-2">Загрузка...</span>
                        </div>
                    ) : displayNotifications.length === 0 ? (
                        <div className="notifications-empty">
                            <p className="mb-0 text-muted">Нет уведомлений</p>
                        </div>
                    ) : (
                        displayNotifications.map((notification) => (
                            <div
                                key={notification.Id}
                                className={`notification-item ${!notification.IsRead ? 'notification-unread' : ''}`}
                            >
                                <div className="notification-content">
                                    <div className="notification-header-item">
                                        <h6 className="notification-title">{notification.Title}</h6>
                                        {!notification.IsRead && (
                                            <span className="notification-dot"></span>
                                        )}
                                    </div>
                                    <p className="notification-message">
                                        {notification.Message}
                                    </p>
                                    <span className="notification-date">
                                        {formatDate(notification.CreatedAt)}
                                    </span>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                {!loading && notifications.length > 0 && (
                    <div className="notifications-footer">
                        <button
                            type="button"
                            className="btn btn-sm btn-primary w-100"
                            onClick={handleViewAll}
                        >
                            Подробно
                        </button>
                    </div>
                )}
            </Dropdown.Menu>
        </Dropdown>
    );
}

export default NotificationsDropdown;

