import React, { useEffect } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import { useTheme } from '../../components/ThemeProvider';
import './SubjectPage.css';
import SubjectJournalContainer from '../../features/study/SubjectJournalContainer';

const SubjectPage = () => {
    const { subjectId, termNumber } = useParams();
    const location = useLocation();
    const { isDark } = useTheme();
    const navigate = useNavigate();
    const initialControlType = location.state?.controlType || 'экзамен';

    // Функция для обновления высоты страницы
    const updatePageHeight = () => {
        const bgElement = document.getElementById('background-gradient');
        if (bgElement) {
            // Принудительно пересчитываем высоту
            const docHeight = Math.max(
                document.body.scrollHeight,
                document.body.offsetHeight,
                document.documentElement.clientHeight,
                document.documentElement.scrollHeight,
                document.documentElement.offsetHeight
            );
            bgElement.style.height = `${docHeight}px`;
        }
    };

    // Обработчик кнопки "Назад"
    const handleBack = () => {
        // Сначала сбрасываем высоту фона, чтобы убрать старое значение
        const bgElement = document.getElementById('background-gradient');
        if (bgElement) {
            bgElement.style.height = 'auto';
        }
        
        // Сбрасываем прокрутку
        window.scrollTo(0, 0);
        
        // Навигация назад
        navigate(-1);
        
        // RouteHeightUpdater в App.js обновит высоту после рендера
    };

    // Обновляем высоту при размонтировании компонента
    useEffect(() => {
        return () => {
            // При размонтировании сбрасываем высоту
            const bgElement = document.getElementById('background-gradient');
            if (bgElement) {
                bgElement.style.height = 'auto';
            }
            
            window.scrollTo(0, 0);
        };
    }, []);

    return (
        <div className="page-wrapper sticky-summary-padding subject-page">
            <div className="card-modern subject-card-main">
                <SubjectJournalContainer
                    subjectId={subjectId}
                            termNumber={termNumber}
                    initialControlType={initialControlType}
                    isDark={isDark}
                    onBack={handleBack}
                />
            </div>
        </div>
    );
};

export default SubjectPage; 