/**
 * Утилиты для подсчета оставшихся занятий по предмету
 */

/**
 * Определяет тип занятия на основе eventType
 * @param {string} eventType - Тип события из расписания
 * @returns {string|null} - 'lecture' | 'practice' | 'laboratory' | null
 */
export const getClassType = (eventType) => {
    if (!eventType) return null;
    const type = eventType.toLowerCase();

    if (type.includes('лекц')) return 'lecture';
    if (type.includes('практ') || type.includes('семинар')) return 'practice';
    if (type.includes('лаборатор')) return 'laboratory';

    return null;
};

/**
 * Проверяет, является ли событие учебным занятием (не формой контроля)
 * @param {string} eventType - Тип события из расписания
 * @returns {boolean}
 */
export const isStudyClass = (eventType) => {
    if (!eventType) return false;
    const type = eventType.toLowerCase();

    // Исключаем формы контроля
    if (type.includes('экзамен') || 
        type.includes('зачет') || 
        type.includes('зачёт') || 
        type.includes('консультация')) {
        return false;
    }

    // Проверяем, что это учебное занятие
    return type.includes('лекц') || 
           type.includes('практ') || 
           type.includes('семинар') || 
           type.includes('лаборатор');
};

/**
 * Находит предмет в расписании по названию (с учетом нечеткого совпадения)
 * @param {Array} schedule - Массив событий расписания
 * @param {string} subjectName - Название предмета
 * @returns {Array} - Массив событий для данного предмета
 */
export const findSubjectEvents = (schedule, subjectName) => {
    if (!schedule || !Array.isArray(schedule) || !subjectName) {
        return [];
    }

    const normalizedSubjectName = subjectName.toLowerCase().trim();

    return schedule.filter(event => {
        if (!event.subject) return false;
        const normalizedEventSubject = event.subject.toLowerCase().trim();

        // Точное совпадение
        if (normalizedEventSubject === normalizedSubjectName) {
            return true;
        }

        // Частичное совпадение (предмет содержит название или наоборот)
        if (normalizedEventSubject.includes(normalizedSubjectName) ||
            normalizedSubjectName.includes(normalizedEventSubject)) {
            return true;
        }

        return false;
    });
};

/**
 * Подсчитывает оставшиеся занятия по предмету
 * @param {Array} schedule - Массив событий расписания
 * @param {string} subjectName - Название предмета
 * @param {Date|string} currentDate - Текущая дата (по умолчанию сегодня)
 * @returns {Object} - Объект с количеством оставшихся занятий по типам
 */
export const calculateRemainingClasses = (schedule, subjectName, currentDate = new Date()) => {
    const subjectEvents = findSubjectEvents(schedule, subjectName);

    // Нормализуем текущую дату
    const today = currentDate instanceof Date 
        ? new Date(currentDate) 
        : new Date(currentDate);
    today.setHours(0, 0, 0, 0);

    const counts = {
        lectures: 0,
        practices: 0,
        laboratories: 0,
        total: 0
    };

    subjectEvents.forEach(event => {
        // Пропускаем формы контроля
        if (!isStudyClass(event.eventType)) {
            return;
        }

        // Парсим дату события
        let eventDate;
        if (typeof event.eventDate === 'string') {
            const [year, month, day] = event.eventDate.split('-').map(Number);
            eventDate = new Date(year, month - 1, day);
        } else {
            eventDate = new Date(event.eventDate);
        }
        eventDate.setHours(0, 0, 0, 0);

        // Считаем только будущие занятия (включая сегодня)
        if (eventDate >= today) {
            const classType = getClassType(event.eventType);
            
            if (classType === 'lecture') {
                counts.lectures++;
            } else if (classType === 'practice') {
                counts.practices++;
            } else if (classType === 'laboratory') {
                counts.laboratories++;
            }

            counts.total++;
        }
    });

    return counts;
};

