/**
 * Утилиты для работы с сохранением предсказаний в localStorage
 */

/**
 * Генерирует ключ для localStorage на основе subjectId и termNumber
 */
export function getPredictionsStorageKey(subjectId, termNumber) {
    return `subjectPredictions-${subjectId}-${termNumber}`;
}

/**
 * Загружает сохранённые предсказания из localStorage
 * @param {string} subjectId
 * @param {string|number} termNumber
 * @returns {Object|null} Объект с predictedRatings, predictedBonusRatings, predictedAttestationRatings, predictionMode или null
 */
export function loadPredictions(subjectId, termNumber) {
    const key = getPredictionsStorageKey(subjectId, termNumber);
    const fromLS = localStorage.getItem(key);
    if (!fromLS) return null;
    
    try {
        const obj = JSON.parse(fromLS);
        if (obj && typeof obj === 'object') {
            return obj;
        }
    } catch (e) {
        // Игнорируем ошибки парсинга
    }
    return null;
}

/**
 * Сохраняет предсказания в localStorage
 * @param {string} subjectId
 * @param {string|number} termNumber
 * @param {Object} data - Объект с predictedRatings, predictedBonusRatings, predictedAttestationRatings, predictionMode
 */
export function savePredictions(subjectId, termNumber, data) {
    const key = getPredictionsStorageKey(subjectId, termNumber);
    localStorage.setItem(key, JSON.stringify(data));
}

/**
 * Удаляет сохранённые предсказания из localStorage
 * @param {string} subjectId
 * @param {string|number} termNumber
 */
export function clearPredictions(subjectId, termNumber) {
    const key = getPredictionsStorageKey(subjectId, termNumber);
    localStorage.removeItem(key);
}

