import React, { useEffect, useRef, useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { Badge, Form } from 'react-bootstrap';
import { studyApi } from '../../api/studyApi';
import { scheduleApi } from '../../api/scheduleApi';
import Section from '../../shared/components/Section';
import { getAllControlPoints, calculateFinalRatingFromJournalData } from '../../shared/lib/rating';
import Loader from '../../shared/components/Loader';
import ErrorAlert from '../../shared/components/ErrorAlert';
import SubjectHeader from '../../components/Study/SubjectHeader';
import SubjectToolbar from '../../components/Study/SubjectToolbar';
import SubjectStickySummaryBar from '../../components/Study/SubjectStickySummaryBar';
import SubjectControlTable from './components/SubjectControlTable';
import SubjectBonusTable from './components/SubjectBonusTable';
import SubjectAttestationTable from './components/SubjectAttestationTable';
import RemainingClassesInfo from './components/RemainingClassesInfo';
import { loadPredictions, savePredictions, clearPredictions } from './lib/predictionsStorage';
import { calculatePredictedRating as calculatePredictedRatingUtil } from './lib/ratingCalculations';
import { calculateRemainingClasses } from './lib/remainingClasses';

// Контейнер принимает все внешние зависимости как пропсы.
// Страница отвечает только за маршрутизацию/тему и обёртку.
const SubjectJournalContainer = ({
    subjectId,
    termNumber,
    initialControlType = 'экзамен',
    isDark,
    onBack
}) => {
    const [subjectData, setSubjectData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [predictedRatings, setPredictedRatings] = useState({});
    const [predictedBonusRatings, setPredictedBonusRatings] = useState({});
    const [predictedAttestationRatings, setPredictedAttestationRatings] = useState({});
    const [predictedTotalRating, setPredictedTotalRating] = useState(null);
    const [controlType, setControlType] = useState(initialControlType);
    const [canSetAgreement, setCanSetAgreement] = useState(false);
    const [isAgreed, setIsAgreed] = useState(false);
    const [predictionMode, setPredictionMode] = useState('percent'); // 'percent' | 'points'
    const [schedule, setSchedule] = useState([]);
    const [loadingSchedule, setLoadingSchedule] = useState(false);

    const { user } = useSelector((state) => state.auth);
    const hasInitializedPredictionsRef = useRef(false);

    useEffect(() => {
        if (!hasInitializedPredictionsRef.current) return;
        const data = {
            predictedRatings,
            predictedBonusRatings,
            predictedAttestationRatings,
            predictionMode
        };
        savePredictions(subjectId, termNumber, data);
    }, [predictedRatings, predictedBonusRatings, predictedAttestationRatings, predictionMode, subjectId, termNumber]);

    const clearSavedPredictions = () => {
        clearPredictions(subjectId, termNumber);
        resetPredictions();
    };

    useEffect(() => {
        const checkAgreementStatus = async () => {
            try {
                if (subjectData?.id) {
                    const response = await studyApi.checkAgreementStatus(subjectData.id);
                    setCanSetAgreement(response);
                    setIsAgreed(subjectData.hasAgreement);
                }
            } catch (err) {
                console.error('Error checking agreement status:', err);
            }
        };

        checkAgreementStatus();
    }, [subjectData]);

    const handleAgreementChange = async (e) => {
        try {
            if (subjectData?.id) {
                await studyApi.setAgreement(subjectData.id, e.target.checked);
                setIsAgreed(e.target.checked);
            }
        } catch (err) {
            console.error('Error setting agreement:', err);
            setIsAgreed(!e.target.checked);
        }
    };

    // Загружаем расписание для подсчета оставшихся занятий
    useEffect(() => {
        const fetchSchedule = async () => {
            const groupId = user?.student?.groupId || user?.student?.group?.id || user?.student?.id;
            if (!groupId) {
                return;
            }

            try {
                setLoadingSchedule(true);
                const scheduleData = await scheduleApi.getGroupSchedule(groupId);
                setSchedule(scheduleData || []);
            } catch (err) {
                console.error('Error fetching schedule:', err);
                // Не показываем ошибку пользователю, просто не загружаем расписание
            } finally {
                setLoadingSchedule(false);
            }
        };

        if (user) {
            fetchSchedule();
        }
    }, [user]);

    useEffect(() => {
        const fetchSubjectData = async () => {
            try {
                setLoading(true);
                setError(null);
                const isCourseWork = controlType?.toLowerCase() === 'курсовые работы';
                const data = await studyApi.getSubjectJournal(subjectId, termNumber, isCourseWork);
                setSubjectData(data);

                const initialPredictions = {};
                const initialBonusPredictions = {};

                if (isCourseWork && data.courseWorksOrProjects) {
                    data.courseWorksOrProjects.forEach(item => {
                        const currentRating = item.rating || 0;
                        initialPredictions[item.name] = currentRating;
                    });
                } else {
                    const allControlPoints = getAllControlPoints(data);
                    allControlPoints.forEach(item => {
                        initialPredictions[item.name] = item.rating;
                    });
                }

                if (data.bonuses) {
                    data.bonuses.forEach(item => {
                        initialBonusPredictions[item.name] = item.rating;
                        if (!item.weight) {
                            item.weight = 1;
                        }
                    });
                }

                const initialAttestationPredictions = {};
                if (data.attestation) {
                    data.attestation.forEach(item => {
                        initialAttestationPredictions[item.name] = item.rating || 0;
                    });
                }

                const lsData = loadPredictions(subjectId, termNumber);

                const effectivePredictedRatings = {
                    ...initialPredictions,
                    ...(lsData?.predictedRatings || {})
                };
                const effectiveBonusPredictions = {
                    ...initialBonusPredictions,
                    ...(lsData?.predictedBonusRatings || {})
                };
                const effectiveAttestationPredictions = {
                    ...initialAttestationPredictions,
                    ...(lsData?.predictedAttestationRatings || {})
                };

                setPredictedRatings(effectivePredictedRatings);
                setPredictedBonusRatings(effectiveBonusPredictions);
                setPredictedAttestationRatings(effectiveAttestationPredictions);
                if (lsData?.predictionMode) {
                    setPredictionMode(lsData.predictionMode);
                }

                hasInitializedPredictionsRef.current = true;

                const { finalRating } = calculatePredictedRatingUtil(
                    isCourseWork ? data.courseWorksOrProjects : getAllControlPoints(data),
                    effectivePredictedRatings,
                    effectiveBonusPredictions,
                    effectiveAttestationPredictions,
                    data.bonuses || [],
                    data.attestation || []
                );
                setPredictedTotalRating(finalRating);
            } catch (err) {
                console.error('Error fetching subject data:', err);
                setError(err.response?.data?.message || err.message || 'Ошибка при загрузке данных');
            } finally {
                setLoading(false);
            }
        };

        fetchSubjectData();
    }, [subjectId, termNumber, controlType]);

    useEffect(() => {
        if (subjectData) {
            const isCourseWork = controlType?.toLowerCase() === 'курсовые работы';
            const controlPoints = isCourseWork && subjectData.courseWorksOrProjects
                ? subjectData.courseWorksOrProjects
                : getAllControlPoints(subjectData);
            const { finalRating } = calculatePredictedRatingUtil(
                controlPoints,
                predictedRatings,
                predictedBonusRatings,
                predictedAttestationRatings,
                subjectData.bonuses || [],
                subjectData.attestation || []
            );
            setPredictedTotalRating(finalRating);
        }
    }, [subjectData, predictedRatings, predictedBonusRatings, predictedAttestationRatings, controlType]);

    const calculateFinalFactRating = () => {
        if (!subjectData) return 0;
        const isCourseWork = controlType?.toLowerCase() === 'курсовые работы';
        return calculateFinalRatingFromJournalData(subjectData, { isCourseWork });
    };


    const handlePredictionChange = (name, value, maxPoint) => {
        if (value === '') {
            setPredictedRatings(prevRatings => ({
                ...prevRatings,
                [name]: ''
            }));
            return;
        }

        let percentValue;
        if (predictionMode === 'points') {
            const points = Math.max(parseFloat(value) || 0, 0);
            const rawMax = parseFloat(maxPoint);
            const safeMax = Number.isFinite(rawMax) && rawMax > 0 ? rawMax : 100;
            percentValue = Math.min((points / safeMax) * 100, 100);
        } else {
            percentValue = Math.min(Math.max(parseFloat(value) || 0, 0), 100);
        }
        setPredictedRatings(prevRatings => ({
            ...prevRatings,
            [name]: percentValue
        }));
    };

    const handleBonusPredictionChange = (name, value) => {
        if (value === '') {
            setPredictedBonusRatings(prevBonusRatings => ({
                ...prevBonusRatings,
                [name]: ''
            }));
            return;
        }

        const numValue = Math.min(Math.max(parseFloat(value) || 0, 0), 100);
        setPredictedBonusRatings(prevBonusRatings => ({
            ...prevBonusRatings,
            [name]: numValue
        }));
    };

    const handleAttestationPredictionChange = (name, value, maxPoint) => {
        if (value === '') {
            setPredictedAttestationRatings(prev => ({
                ...prev,
                [name]: ''
            }));
            return;
        }
        let percentValue;
        if (predictionMode === 'points') {
            const points = Math.max(parseFloat(value) || 0, 0);
            const rawMax = parseFloat(maxPoint);
            const safeMax = Number.isFinite(rawMax) && rawMax > 0 ? rawMax : 100;
            percentValue = Math.min((points / safeMax) * 100, 100);
        } else {
            percentValue = Math.min(Math.max(parseFloat(value) || 0, 0), 100);
        }
        setPredictedAttestationRatings(prev => ({
            ...prev,
            [name]: percentValue
        }));
    };

    const resetPredictions = () => {
        if (!subjectData) return;
        const isCourseWork = controlType?.toLowerCase() === 'курсовые работы';

        const initialPredictions = {};
        if (isCourseWork && subjectData.courseWorksOrProjects) {
            subjectData.courseWorksOrProjects.forEach(item => {
                const currentRating = item.rating || 0;
                initialPredictions[item.name] = currentRating;
            });
        } else {
            const allControlPoints = getAllControlPoints(subjectData);
            allControlPoints.forEach(item => {
                initialPredictions[item.name] = item.rating;
            });
        }

        const initialBonusPredictions = {};
        if (subjectData.bonuses) {
            subjectData.bonuses.forEach(item => {
                initialBonusPredictions[item.name] = item.rating;
            });
        }

        const initialAttestationPredictions = {};
        if (subjectData.attestation) {
            subjectData.attestation.forEach(item => {
                initialAttestationPredictions[item.name] = item.rating || 0;
            });
        }
        setPredictedRatings(initialPredictions);
        setPredictedBonusRatings(initialBonusPredictions);
        setPredictedAttestationRatings(initialAttestationPredictions);
    };

    const quickSetPrediction = (name, value, maxPoint) => {
        if (predictionMode === 'points' && maxPoint) {
            const percent = Math.min((value / maxPoint) * 100, 100);
            setPredictedRatings(prev => ({ ...prev, [name]: percent }));
        } else {
            setPredictedRatings(prev => ({ ...prev, [name]: value }));
        }
    };

    const quickSetAttestationPrediction = (name, value, maxPoint) => {
        if (predictionMode === 'points' && maxPoint) {
            const percent = Math.min((value / maxPoint) * 100, 100);
            setPredictedAttestationRatings(prev => ({ ...prev, [name]: percent }));
        } else {
            setPredictedAttestationRatings(prev => ({ ...prev, [name]: value }));
        }
    };

    const quickSetBonusPrediction = (name, value) => {
        setPredictedBonusRatings(prev => ({ ...prev, [name]: value }));
    };

    const finalFactRating = subjectData ? calculateFinalFactRating() : 0;
    const finalPredictedRating = predictedTotalRating !== null ? predictedTotalRating : 0;

    // Вычисляем оставшиеся занятия
    const remainingClasses = useMemo(() => {
        if (!subjectData?.disciplineName || !schedule || schedule.length === 0) {
            return null;
        }
        return calculateRemainingClasses(schedule, subjectData.disciplineName);
    }, [schedule, subjectData?.disciplineName]);

    if (loading) {
        return <Loader className="subject-loading" />;
    }

    if (error) {
        return <ErrorAlert message={error} className="subject-error" />;
    }

    if (!subjectData) {
        return null;
    }

    return (
        <>
            <div className="card-modern-header subject-card-header">
                <div className="subject-header-top">
                    <div className="subject-header-left">
                        <SubjectHeader
                            loading={loading}
                            subjectData={subjectData}
                            termNumber={termNumber}
                            controlType={controlType}
                            subjectId={subjectId}
                            error={error}
                            canSetAgreement={false}
                            isAgreed={false}
                            onAgreementChange={() => {}}
                            onBack={onBack}
                        />
                        {!loading && subjectData && (
                            <RemainingClassesInfo 
                                remainingClasses={remainingClasses}
                                loading={loadingSchedule}
                            />
                        )}
                    </div>
                    {canSetAgreement && subjectData && (
                        <div className="subject-agreement-block">
                            {subjectData.hasAgreement && (
                                <Badge bg="primary" className="subject-agreement-badge">
                                    Рейтинг на момент согласия:{' '}
                                    {subjectData.agreementRating.toFixed(2)}
                                </Badge>
                            )}
                            <Form.Check
                                type="checkbox"
                                id="agreement-checkbox"
                                label="Согласен с оценкой"
                                checked={isAgreed}
                                onChange={handleAgreementChange}
                                disabled={!canSetAgreement}
                                className="subject-agreement-toggle"
                            />
                        </div>
                    )}
                </div>
            </div>

            <SubjectToolbar
                predictionMode={predictionMode}
                setPredictionMode={setPredictionMode}
                onResetPredictions={resetPredictions}
                onClearSavedPredictions={clearSavedPredictions}
            />

            {controlType?.toLowerCase() === 'курсовые работы' ? (
                <Section
                    title="Курсовая работа"
                    caption="Оценки и предсказания по курсовым работам"
                >
                    <div className="subject-page-tbl-box">
                        <SubjectControlTable
                            items={subjectData.courseWorksOrProjects}
                            predictedRatings={predictedRatings}
                            predictionMode={predictionMode}
                            controlType={controlType}
                            onPredictionChange={handlePredictionChange}
                            onQuickSet={quickSetPrediction}
                        />
                    </div>
                </Section>
            ) : (
                <Section
                    title="Текущий контроль"
                    caption="Рейтинг по всем формам текущего контроля"
                >
                    <div className="subject-page-tbl-box">
                        <SubjectControlTable
                            items={getAllControlPoints(subjectData)}
                            predictedRatings={predictedRatings}
                            predictionMode={predictionMode}
                            controlType={controlType}
                            onPredictionChange={handlePredictionChange}
                            onQuickSet={quickSetPrediction}
                        />
                    </div>
                </Section>
            )}

            {subjectData.bonuses && subjectData.bonuses.length > 0 && (
                <Section
                    title="Бонусы"
                    caption="Дополнительные активности, влияющие на итоговый рейтинг"
                >
                    <div className="subject-page-tbl-box">
                        <SubjectBonusTable
                            items={subjectData.bonuses}
                            predictedRatings={predictedBonusRatings}
                            controlType={controlType}
                            onPredictionChange={handleBonusPredictionChange}
                            onQuickSet={quickSetBonusPrediction}
                        />
                    </div>
                </Section>
            )}

            {subjectData.attestation && subjectData.attestation.length > 0 && (
                <Section
                    title="Аттестация"
                    caption="Итоговые оценивания и их влияние на общий рейтинг"
                    className="subject-section-attestation"
                >
                    <div className="subject-page-tbl-box">
                        <SubjectAttestationTable
                            items={subjectData.attestation}
                            predictedRatings={predictedAttestationRatings}
                            predictionMode={predictionMode}
                            controlType={controlType}
                            onPredictionChange={handleAttestationPredictionChange}
                            onQuickSet={quickSetAttestationPrediction}
                        />
                    </div>
                </Section>
            )}

            <SubjectStickySummaryBar
                isDark={isDark}
                controlType={controlType}
                finalFactRating={finalFactRating}
                finalPredictedRating={finalPredictedRating}
            />
        </>
    );
};

export default SubjectJournalContainer;


