/**
 * Функции для расчёта предсказанных рейтингов
 * Все функции чистые (pure functions) - не зависят от React или внешнего состояния
 */

/**
 * Рассчитывает предсказанный рейтинг на основе контрольных точек, бонусов и аттестации
 * @param {Array} controlPoints - Массив контрольных точек (текущий контроль или курсовые)
 * @param {Object} ratings - Объект с предсказанными рейтингами для контрольных точек { name: rating }
 * @param {Object} bonusRatings - Объект с предсказанными рейтингами для бонусов { name: rating }
 * @param {Object} attestationRatings - Объект с предсказанными рейтингами для аттестации { name: rating }
 * @param {Array} bonuses - Массив бонусов из subjectData
 * @param {Array} attestation - Массив аттестаций из subjectData
 * @returns {Object} { baseRating, bonusContribution, finalRating }
 */
export function calculatePredictedRating(
    controlPoints,
    ratings,
    bonusRatings = {},
    attestationRatings = {},
    bonuses = [],
    attestation = []
) {
    // Расчет основного рейтинга
    let totalWeightedRating = 0;
    let totalWeight = 0;

    controlPoints.forEach(item => {
        const predictedRating = ratings[item.name] || 0;
        const weight = item.weight;
        totalWeightedRating += (predictedRating * weight);
        totalWeight += weight;
    });

    const baseRating = totalWeight > 0 ? (totalWeightedRating / totalWeight) : 0;

    // Расчет бонусного рейтинга
    // Каждый бонус дает свой процент (0-100%), и все бонусы вместе могут дать максимум +15% к рейтингу
    // Вклад каждого бонуса пропорционален его весу
    let bonusContribution = 0;
    if (bonuses && bonuses.length > 0) {
        let totalBonusWeight = 0;
        
        // Сначала вычисляем общий вес всех бонусов
        bonuses.forEach(item => {
            totalBonusWeight += (item.weight || 1);
        });

        // Затем вычисляем вклад каждого бонуса пропорционально его весу
        bonuses.forEach(item => {
            const bonusRating = bonusRatings[item.name] || 0;
            const weight = item.weight || 1;
            // Доля этого бонуса в общем весе
            const weightShare = totalBonusWeight > 0 ? (weight / totalBonusWeight) : 0;
            // Вклад этого бонуса: его процент от его доли в 15%
            const itemContribution = (bonusRating / 100) * 15 * weightShare;
            bonusContribution += itemContribution;
        });

        // Ограничиваем максимумом 15%
        bonusContribution = Math.min(bonusContribution, 15);
    }

    // Базовый рейтинг с учетом бонусов (до аттестации)
    const preAttestationRating = baseRating + bonusContribution;

    // Расчет рейтинга аттестации (из предсказаний)
    let attestationRating = 0;
    if (attestation && attestation.length > 0) {
        let totalAttestationWeighted = 0;
        let totalAttestationWeight = 0;
        attestation.forEach(item => {
            const weight = item.weight || 1;
            const rating = attestationRatings[item.name] === '' 
                ? 0 
                : (attestationRatings[item.name] ?? item.rating ?? 0);
            totalAttestationWeighted += rating * weight;
            totalAttestationWeight += weight;
        });
        attestationRating = totalAttestationWeight > 0 ? (totalAttestationWeighted / totalAttestationWeight) : 0;
    }

    // Применяем формулу с аттестацией, если ее рейтинг не ноль
    const finalRating = attestationRating > 0
        ? (preAttestationRating * 0.6) + (attestationRating * 0.4)
        : preAttestationRating;

    return {
        baseRating,
        bonusContribution,
        finalRating
    };
}

