export function getControlTypeBadgeClass(controlType) {
    if (!controlType) return 'badge-control-empty';

    const typeRaw = controlType.toString().toLowerCase();

    if (typeRaw === 'зачет' || typeRaw === 'дифференцированный зачет') {
        return 'badge-control-credit';
    }
    if (typeRaw === 'экзамен' || typeRaw === 'курсовые работы') {
        return 'badge-control-exam';
    }
    if (typeRaw.includes('консультация') || typeRaw.includes('промежуточной аттестации')) {
        return 'badge-control-consultation';
    }

    return 'badge-control-empty';
}

export function getRatingColor(rating, controlType) {
    if (!rating && rating !== 0) return 'secondary';

    const typeRaw = (controlType || 'экзамен').toString().toLowerCase();

    if (typeRaw === 'зачет' || typeRaw === 'дифференцированный зачет') {
        return rating >= 59.01 ? 'success text-dark' : 'danger';
    }

    if (typeRaw === 'экзамен' || typeRaw === 'курсовые работы') {
        if (rating < 59.01) return 'danger text-dark';
        if (rating < 74.01) return 'warning text-dark';
        if (rating < 84.01) return 'primary';
        return 'success text-dark';
    }

    return 'secondary';
}


