import React from 'react';
import { Alert } from 'react-bootstrap';

/**
 * Универсальный компонент для отображения ошибок
 * @param {Object} props
 * @param {string} props.message - Текст ошибки
 * @param {string} [props.className] - Дополнительные CSS классы
 * @param {string} [props.variant] - Вариант алерта ('danger' по умолчанию)
 */
function ErrorAlert({ message, className = '', variant = 'danger' }) {
    if (!message) return null;
    
    return (
        <Alert variant={variant} className={`error-alert ${className}`}>
            {message}
        </Alert>
    );
}

export default ErrorAlert;

