import axios from 'axios';

const BASE_URL = 'https://online.susu.ru/microgateway/api/Notifications';

// Ключ для локального кеша
const STORAGE_KEY = 'univeris-notifications';

// Создаем экземпляр axios с базовой конфигурацией
const api = axios.create({
    baseURL: BASE_URL,
});

// Добавляем перехватчик для добавления токена к каждому запросу
api.interceptors.request.use(
    (config) => {
        const token = localStorage.getItem('authToken');
        if (token) {
            config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);

const notificationsApi = {
    // Получаем уведомления пользователя
    getUserNotifications: async () => {
        try {
            const response = await api.get('/GetUserNotifications');
            const data = response.data;
            localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
            return data;
        } catch (error) {
            console.error('Error fetching notifications, trying cache:', error);
            const cached = localStorage.getItem(STORAGE_KEY);
            if (cached) {
                try {
                    return JSON.parse(cached);
                } catch (e) {
                    console.error('Failed to parse cached notifications:', e);
                }
            }
            throw error;
        }
    },

    // Помечаем уведомление как прочитанное
    setNotificationAsRead: async (notificationId) => {
        try {
            const formData = new FormData();
            formData.append('notificationId', notificationId);

            // Axios автоматически установит правильный Content-Type с boundary для FormData
            const response = await api.post('/SetNotificationAsRead', formData);
            return response.data;
        } catch (error) {
            console.error('Error marking notification as read:', error);
            throw error;
        }
    },
};

export { notificationsApi };

