import axios from 'axios';

const BASE_URL = 'https://online.susu.ru/microgateway/api/Schedule';

// Ключ для локального кеша
const STORAGE_KEY = (groupId) => `univeris-schedule-${groupId}`;

// Создаем экземпляр axios с базовой конфигурацией
const api = axios.create({
    baseURL: BASE_URL,
});

// Добавляем перехватчик для добавления токена к каждому запросу
api.interceptors.request.use(
    (config) => {
        const token = localStorage.getItem('authToken');
        if (token) {
            config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);

const scheduleApi = {
    // Получаем расписание группы по groupId
    getGroupSchedule: async (groupId) => {
        const storageKey = STORAGE_KEY(groupId);
        try {
            const response = await api.get(`/GetGroupSchedule/${groupId}`);
            const data = response.data;
            localStorage.setItem(storageKey, JSON.stringify(data));
            return data;
        } catch (error) {
            console.error('Error fetching schedule, trying cache:', error);
            const cached = localStorage.getItem(storageKey);
            if (cached) {
                try {
                    return JSON.parse(cached);
                } catch (e) {
                    console.error('Failed to parse cached schedule:', e);
                }
            }
            throw error;
        }
    },
};

export { scheduleApi };

