import React from 'react';

/**
 * Унифицированный блок раздела с заголовком и подзаголовком.
 * Подходит для секций на страницах предмета, учебного плана и т.п.
 */
const Section = ({ title, caption, className = '', children }) => {
    return (
        <section className={`subject-section ${className}`.trim()}>
            <div className="subject-section-header">
                <h3 className="subject-section-title">{title}</h3>
                {caption && (
                    <p className="subject-section-caption">
                        {caption}
                    </p>
                )}
            </div>
            {children}
        </section>
    );
};

export default Section;


