import React from 'react';
import { Form, InputGroup } from 'react-bootstrap';
import './PredictionInput.css';

/**
 * Универсальный компонент для ввода предсказаний (проценты или баллы)
 * @param {Object} props
 * @param {string} props.mode - Режим: 'percent' или 'points'
 * @param {number|string} props.value - Текущее значение (в процентах)
 * @param {number} [props.maxPoint] - Максимальное количество баллов (для режима 'points')
 * @param {Function} props.onChange - Коллбэк при изменении значения
 * @param {Function} [props.onQuickSet] - Коллбэк для быстрой установки (0, 50, 100)
 * @param {string} [props.className] - Дополнительные CSS классы
 */
function PredictionInput({ 
    mode, 
    value, 
    maxPoint, 
    onChange, 
    onQuickSet,
    className = '' 
}) {
    // Преобразуем процент в баллы для отображения в режиме points
    const displayValue = mode === 'points'
        ? (() => {
            const pct = value ?? '';
            if (pct === '' || maxPoint == null) return '';
            const pts = (Number(pct) * Number(maxPoint)) / 100;
            return Number.isFinite(pts) ? Math.round(pts * 100) / 100 : '';
        })()
        : (value ?? '');

    const maxValue = mode === 'points' ? (maxPoint ?? 100) : 100;
    const placeholder = mode === 'points' ? 'Введите баллы' : 'Введите %';
    const shortPlaceholder = mode === 'points' ? 'Введите баллы' : '%';

    // Значение для ползунка (в процентах, 0-100)
    // Используем точное значение, без округления до шага, чтобы сохранить точность
    const rawSliderValue = value === '' || value == null ? 0 : Math.min(Math.max(Number(value) || 0, 0), 100);
    const sliderValue = rawSliderValue;

    // Шаг для слайдера: используем очень маленький шаг, чтобы ползунок мог достичь любого значения
    // Округление до нужного шага выполняется в handleSliderChange
    const sliderStep = mode === 'points' && maxPoint && maxPoint > 0
        ? 0.01  // Очень маленький шаг для точного позиционирования
        : 0.01;  // Очень маленький шаг для режима percent тоже

    // Значение для отображения рядом со слайдером
    // Используем точное значение процента для вычисления баллов, чтобы сохранить точность
    const sliderDisplayValue = mode === 'points' && maxPoint
        ? (() => {
            const points = (rawSliderValue / 100) * maxPoint;
            // Округляем до 2 знаков после запятой для отображения, но сохраняем точность в значении
            return Math.round(points * 100) / 100;
        })()
        : Math.round(rawSliderValue);  // Показываем проценты в режиме percent

    const handleSliderChange = (e) => {
        let newValue = parseFloat(e.target.value);
        
        // Ограничиваем диапазоном 0-100
        newValue = Math.max(0, Math.min(100, newValue));
        
        // Выравниваем значение по шагу для точного позиционирования
        if (mode === 'points' && maxPoint && maxPoint > 0) {
            const step = 100 / maxPoint;
            // Если значение очень близко к 100% (>= 99% или >= последнего шага), устанавливаем 100%
            // Это позволяет достичь максимума при движении ползунка вправо
            const lastStepValue = (maxPoint - 1) * step;
            if (newValue >= 99 || newValue >= lastStepValue) {
                newValue = 100;
            } else {
                // Округляем до ближайшего шага (соответствующего целому числу баллов)
                newValue = Math.round(newValue / step) * step;
            }
            // Снова ограничиваем диапазоном 0-100
            newValue = Math.max(0, Math.min(100, newValue));
        } else {
            // В режиме percent округляем до целого
            newValue = Math.round(newValue);
        }
        
        if (onQuickSet) {
            // Всегда передаем проценты (0-100), независимо от режима
            // Конвертация в баллы/проценты выполняется в handleQuickSet таблицы
            onQuickSet(newValue);
        }
    };

    // Обработчик двойного клика по ползунку для быстрой установки на 50%
    const handleSliderDoubleClick = (e) => {
        e.preventDefault();
        e.stopPropagation();
        
        if (onQuickSet) {
            // Устанавливаем 50%
            let newValue = 50;
            
            // В режиме points выравниваем по шагу
            if (mode === 'points' && maxPoint && maxPoint > 0) {
                const step = 100 / maxPoint;
                // Округляем до ближайшего шага
                newValue = Math.round(50 / step) * step;
            }
            
            onQuickSet(newValue);
        }
    };

    // Обработчик клика по значению для быстрой установки на 50%
    const handleValueClick = (e) => {
        e.preventDefault();
        e.stopPropagation();
        
        if (onQuickSet) {
            // Устанавливаем 50%
            let newValue = 50;
            
            // В режиме points выравниваем по шагу
            if (mode === 'points' && maxPoint && maxPoint > 0) {
                const step = 100 / maxPoint;
                // Округляем до ближайшего шага
                newValue = Math.round(50 / step) * step;
            }
            
            onQuickSet(newValue);
        }
    };

    return (
        <div className={`prediction-input-wrapper ${className}`}>
            <InputGroup>
                <Form.Control
                    type="number"
                    min="0"
                    max={maxValue}
                    step="1"
                    value={displayValue}
                    onChange={(e) => onChange(e.target.value)}
                    onBlur={(e) => onChange(e.target.value)}
                    placeholder={placeholder}
                    className="d-none d-sm-block"
                />
                {mode !== 'points' && (
                    <InputGroup.Text className="d-none d-sm-block percent-border-right">%</InputGroup.Text>
                )}
                <Form.Control
                    type="number"
                    min="0"
                    max={maxValue}
                    step="1"
                    value={displayValue}
                    onChange={(e) => onChange(e.target.value)}
                    onBlur={(e) => onChange(e.target.value)}
                    placeholder={shortPlaceholder}
                    className="d-sm-none"
                />
            </InputGroup>
            {onQuickSet && (
                <div className="prediction-slider-wrapper">
                    <div className="prediction-slider-container">
                        <input
                            type="range"
                            min="0"
                            max="100"
                            step={sliderStep}
                            value={sliderValue}
                            onChange={handleSliderChange}
                            onDoubleClick={handleSliderDoubleClick}
                            className="prediction-slider"
                            aria-label="Рейтинг"
                            title="Двойной клик для установки 50%"
                        />
                        <div 
                            className="prediction-slider-value"
                            onClick={handleValueClick}
                            title="Клик для установки 50%"
                            style={{ cursor: 'pointer' }}
                        >
                            {sliderDisplayValue}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

export default PredictionInput;

