import React, { useState, useEffect } from 'react';
import { Navbar, Nav, NavDropdown, Button, Spinner, Badge } from 'react-bootstrap';
import { useNavigate, useLocation } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { logout } from '../../store/slices/authSlice';
import { authApi } from '../../api/authApi';
import { studyApi } from '../../api/studyApi';
import QROverlay from '../../shared/components/QROverlay';
import NotificationsDropdown from '../../shared/components/NotificationsDropdown';
import './Header.css';

const Header = ({showChangelog, setShowChangelog}) => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const location = useLocation();
    const [studyPlan, setStudyPlan] = useState(null);
    const [subjects, setSubjects] = useState([]);
    const [loadingSubjects, setLoadingSubjects] = useState(false);
    const [currentTerm, setCurrentTerm] = useState(null);
    const [showQR, setShowQR] = useState(false);
    const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);
    
    // Получаем passTicket из Redux store
    const passTicket = useSelector((state) => state.auth?.user?.passTicket);

    // Функция для получения класса badge по типу контроля
    const getControlTypeBadgeClass = (controlType) => {
        if (!controlType) return 'badge-control-empty';
        
        const typeRaw = controlType.toString().toLowerCase();
        
        if (typeRaw === 'зачет' || typeRaw === 'дифференцированный зачет') {
            return 'badge-control-credit';
        }
        if (typeRaw === 'экзамен' || typeRaw === 'курсовые работы') {
            return 'badge-control-exam';
        }
        if (typeRaw.includes('консультация') || typeRaw.includes('промежуточной аттестации')) {
            return 'badge-control-consultation';
        }
        
        return 'badge-control-empty';
    };

    // Функция для получения цвета рейтинга
    const getRatingColor = (rating, controlType) => {
        if (!rating && rating !== 0) return 'secondary';
        
        const typeRaw = (controlType || '').toString().toLowerCase();
        
        // Для зачёта и дифференцированного зачёта
        if (typeRaw === 'зачет' || typeRaw === 'дифференцированный зачет') {
            return rating >= 59.01 ? 'success text-dark' : 'danger text-dark';
        }
        
        // Для экзамена и курсовых работ
        if (typeRaw === 'экзамен' || typeRaw === 'курсовые работы') {
            if (rating < 59.01) return 'danger text-dark';
            if (rating < 74.01) return 'warning text-dark';
            if (rating < 84.01) return 'primary';
            return 'success text-dark';
        }
        
        // Для остальных типов контроля
        return 'secondary';
    };

    // Подсчет фактического рейтинга по данным журнала предмета
    const calculateFinalRatingFromJournal = (subjectData) => {
        if (!subjectData) return null;

        const getAllControlPoints = (data) => {
            const currentControl = data.currentControl || [];
            const labs = data.labs || [];
            return [...currentControl, ...labs];
        };

        const allControlPoints = getAllControlPoints(subjectData);

        // Если нет ни одного элемента ни в текущем контроле/лабах, ни в аттестации — считаем,
        // что вообще нет данных и возвращаем null
        const hasAnyData =
            (allControlPoints && allControlPoints.length > 0) ||
            (subjectData.attestation && subjectData.attestation.length > 0);
        if (!hasAnyData) {
            return null;
        }

        // Текущий контроль (без бонусов)
        let currentWeighted = 0;
        let currentWeight = 0;
        allControlPoints.forEach((ctrl) => {
            const w = ctrl.weight || 1;
            const r = ctrl.rating || 0;
            currentWeighted += r * w;
            currentWeight += w;
        });
        const currentBase = currentWeight > 0 ? currentWeighted / currentWeight : 0;

        // Аттестация (если есть)
        let attAvg = 0;
        if (subjectData.attestation && subjectData.attestation.length > 0) {
            let attWeighted = 0;
            let attWeight = 0;
            subjectData.attestation.forEach((att) => {
                const w = att.weight || 1;
                const r = att.rating || 0;
                attWeighted += r * w;
                attWeight += w;
            });
            attAvg = attWeight > 0 ? attWeighted / attWeight : 0;
        }

        // Итог: если аттестация есть и не нулевая, применяем формулу 60/40
        const final =
            attAvg > 0
                ? currentBase * 0.6 + attAvg * 0.4
                : currentBase;

        return final;
    };

    // Загружаем учебный план для получения текущего семестра
    useEffect(() => {
        const fetchStudyPlan = async () => {
            try {
                const planData = await studyApi.getStudyPlan();
                setStudyPlan(planData);
                if (planData.currentTerm) {
                    setCurrentTerm(planData.currentTerm);
                }
            } catch (err) {
                console.error('Error fetching study plan in header:', err);
            }
        };

        fetchStudyPlan();
    }, []);

    // Загружаем предметы для текущего семестра
    useEffect(() => {
        const fetchSubjects = async () => {
            if (!currentTerm) return;
            
            try {
                setLoadingSubjects(true);
                const subjectsData = await studyApi.getSubjects(currentTerm);
                const filteredSubjects = subjectsData
                    .filter(
                        subject =>
                            subject.termNumber === currentTerm &&
                            subject.instructors &&
                            subject.instructors.length > 0
                    )
                    .sort((a, b) => {
                        // Сортируем: сначала экзамены, затем остальные
                        if (a.controlType.toLowerCase() === 'экзамен' && b.controlType.toLowerCase() !== 'экзамен') {
                            return -1;
                        }
                        if (a.controlType.toLowerCase() !== 'экзамен' && b.controlType.toLowerCase() === 'экзамен') {
                            return 1;
                        }
                        return 0;
                    });

                // Для предметов, у которых rating <= 0, пробуем посчитать рейтинг по журналу
                const subjectsWithRatings = await Promise.all(
                    filteredSubjects.map(async (subject) => {
                        if (subject.rating && subject.rating > 0) {
                            return subject;
                        }

                        try {
                            const isCourseWork = subject.controlType?.toLowerCase() === 'курсовые работы';
                            const journal = await studyApi.getSubjectJournal(
                                subject.disciplineId,
                                currentTerm,
                                isCourseWork
                            );
                            const calculatedRating = calculateFinalRatingFromJournal(journal);

                            // Если по журналу вообще есть данные, но итоговый рейтинг может быть даже 0,
                            // считаем, что "данные есть" и показываем 0/любой другой факт вместо "Нет данных"
                            if (calculatedRating !== null && calculatedRating !== undefined) {
                                return {
                                    ...subject,
                                    rating: calculatedRating,
                                    hasJournalData: true,
                                };
                            }
                        } catch (e) {
                            console.error('Error fetching subject journal for discipline', subject.disciplineId, e);
                        }

                        // Если что-то пошло не так, возвращаем предмет как есть
                        return subject;
                    })
                );
                
                setSubjects(subjectsWithRatings);
            } catch (err) {
                console.error('Error fetching subjects in header:', err);
            } finally {
                setLoadingSubjects(false);
            }
        };

        fetchSubjects();
    }, [currentTerm]);

    const handleLogout = async () => {
        try {
            await authApi.logout();
        } catch (error) {
            console.error('Logout error:', error);
        } finally {
            dispatch(logout());
            navigate('/login');
        }
    };

    const handleSubjectClick = (subjectId, controlType) => {
        navigate(`/subject/${subjectId}/${currentTerm}`, { state: { controlType } });
    };

    const isActiveRoute = (path) => {
        // Учитываем HashRouter - убираем хэш из пути
        const currentPath = location.pathname.replace(/^#/, '') || '/';
        
        if (path === '/') {
            return currentPath === '/' || currentPath === '';
        }
        return currentPath.startsWith(path);
    };

    // Проверка активного состояния для выпадающего меню "Сервисы"
    const isServicesActive = () => {
        const currentPath = location.pathname.replace(/^#/, '') || '/';
        return currentPath === '/edususu';
    };

    return (
        <Navbar 
            expand="lg" 
            className="app-header"
        >
            <div className="header-container">
                <Navbar.Brand 
                    href="#" 
                    onClick={(e) => {
                        e.preventDefault();
                        navigate('/');
                    }}
                    className="header-brand"
                >
                    <span className="header-brand-full">Универис</span>
                    <span className="header-brand-short">У</span>
                </Navbar.Brand>
                
                <Navbar.Toggle aria-controls="basic-navbar-nav" />
                
                <Navbar.Collapse id="basic-navbar-nav">
                    <Nav className="me-auto header-nav">
                        <Nav.Link
                            active={isActiveRoute('/')}
                            onClick={(e) => {
                                e.preventDefault();
                                navigate('/');
                            }}
                            className="header-nav-link"
                        >
                            Учебный план
                        </Nav.Link>
                        <Nav.Link
                            active={isActiveRoute('/schedule')}
                            onClick={(e) => {
                                e.preventDefault();
                                navigate('/schedule');
                            }}
                            className="header-nav-link"
                        >
                            Расписание
                        </Nav.Link>
                        
                        <NavDropdown
                            title={
                                <span>
                                    Предметы
                                    {loadingSubjects && (
                                        <Spinner 
                                            animation="border" 
                                            size="sm" 
                                            className="ms-2"
                                            style={{ width: '0.8rem', height: '0.8rem' }}
                                        />
                                    )}
                                </span>
                            }
                            id="subjects-dropdown"
                            className="header-dropdown"
                            disabled={subjects.length === 0 && !loadingSubjects}
                        >
                            {loadingSubjects ? (
                                <NavDropdown.Item disabled>
                                    <div className="d-flex align-items-center gap-2">
                                        <Spinner animation="border" size="sm" />
                                        <span>Загрузка...</span>
                                    </div>
                                </NavDropdown.Item>
                            ) : subjects.length === 0 ? (
                                <NavDropdown.Item disabled>
                                    Нет предметов
                                </NavDropdown.Item>
                            ) : (
                                subjects.map((subject) => (
                                    <NavDropdown.Item
                                        key={subject.disciplineId}
                                        onClick={() => handleSubjectClick(subject.disciplineId, subject.controlType)}
                                        className="header-dropdown-item"
                                    >
                                        <div className="dropdown-item-content">
                                            <div className="dropdown-item-header">
                                                <span className="dropdown-item-name">{subject.disciplineName}</span>
                                                {(subject.hasJournalData || (subject.rating && subject.rating > 0)) ? (
                                                    <Badge bg={getRatingColor(subject.rating || 0, subject.controlType)} className="dropdown-item-rating">
                                                        {(subject.rating || 0).toFixed(1)}
                                                    </Badge>
                                                ) : (
                                                    <Badge className={`dropdown-item-rating badge-control-empty`}>
                                                        —
                                                    </Badge>
                                                )}
                                            </div>
                                            <span className="dropdown-item-type">{subject.controlType}</span>
                                        </div>
                                    </NavDropdown.Item>
                                ))
                            )}
                        </NavDropdown>
                        
                        <NavDropdown
                            title="Сервисы"
                            id="services-dropdown"
                            className={`header-dropdown ${isServicesActive() ? 'active' : ''}`}
                        >
                            <NavDropdown.Item
                                onClick={() => navigate('/edususu')}
                                className="header-dropdown-item"
                            >
                                <div className="dropdown-item-content">
                                    <span className="dropdown-item-name">EduSusu</span>
                                </div>
                            </NavDropdown.Item>
                            <NavDropdown.Item
                                onClick={() => window.open('https://studlk.susu.ru/Account/Login', '_blank', 'noopener,noreferrer')}
                                className="header-dropdown-item"
                            >
                                <div className="dropdown-item-content">
                                    <span className="dropdown-item-name">
                                        <svg 
                                            width="12" 
                                            height="12" 
                                            viewBox="0 0 24 24" 
                                            fill="none" 
                                            stroke="currentColor" 
                                            strokeWidth="2" 
                                            strokeLinecap="round" 
                                            strokeLinejoin="round"
                                            style={{ display: 'inline-block', verticalAlign: 'middle', marginRight: '6px', opacity: 0.7 }}
                                        >
                                            <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" />
                                            <polyline points="15 3 21 3 21 9" />
                                            <line x1="10" y1="14" x2="21" y2="3" />
                                        </svg>
                                        Универис
                                    </span>
                                </div>
                            </NavDropdown.Item>
                            <NavDropdown.Item
                                onClick={() => window.open('https://syncshare.naloaty.me/app/accounts/login', '_blank', 'noopener,noreferrer')}
                                className="header-dropdown-item"
                            >
                                <div className="dropdown-item-content">
                                    <span className="dropdown-item-name">
                                        <svg 
                                            width="12" 
                                            height="12" 
                                            viewBox="0 0 24 24" 
                                            fill="none" 
                                            stroke="currentColor" 
                                            strokeWidth="2" 
                                            strokeLinecap="round" 
                                            strokeLinejoin="round"
                                            style={{ display: 'inline-block', verticalAlign: 'middle', marginRight: '6px', opacity: 0.7 }}
                                        >
                                            <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" />
                                            <polyline points="15 3 21 3 21 9" />
                                            <line x1="10" y1="14" x2="21" y2="3" />
                                        </svg>
                                        SyncShare
                                    </span>
                                </div>
                            </NavDropdown.Item>
                        </NavDropdown>
                    </Nav>
                    
                    <Nav className="header-actions">
                        <NotificationsDropdown 
                            unreadCount={unreadNotificationsCount}
                            onNotificationsUpdate={setUnreadNotificationsCount}
                        />
                        
                        {passTicket && (
                            <Button
                                variant='outline-primary'
                                className='icon-btn header-action-btn'
                                onClick={() => setShowQR(true)}
                            >
                                Пропуск
                            </Button>
                        )}
                        
                        <Button
                            variant='outline-primary'
                            className='icon-btn header-action-btn'
                            onClick={() => setShowChangelog(true)}  
                            >
                            Изменения
                        </Button>
                        
                        <Button
                            variant="outline-danger"
                            className="icon-btn icon-btn-danger header-action-btn header-logout-btn"
                            onClick={handleLogout}
                        >
                            <span className="d-none d-sm-inline">Выйти</span>
                            <span className="d-inline d-sm-none">🚪</span>
                        </Button>
                        
                    </Nav>
                </Navbar.Collapse>
            </div>
            
            <QROverlay
                show={showQR}
                onHide={() => setShowQR(false)}
                value={passTicket}
                title="Пропуск"
            />
        </Navbar>
    );
};

export default Header;

