import React, { createContext, useContext, useState, useEffect } from 'react';

const ThemeContext = createContext();

export const useTheme = () => useContext(ThemeContext);

export const ThemeProvider = ({ children }) => {
    const [isDark, setIsDark] = useState(() => {
        const savedTheme = localStorage.getItem('theme');
        const initialTheme = savedTheme ? savedTheme === 'dark' : true; // По умолчанию тёмная тема
        
        // Устанавливаем тему синхронно при инициализации
        if (typeof document !== 'undefined') {
            const theme = initialTheme ? 'dark' : 'light';
            document.body.dataset.theme = theme;
            document.documentElement.dataset.theme = theme;
        }
        
        return initialTheme;
    });

    useEffect(() => {
        localStorage.setItem('theme', isDark ? 'dark' : 'light');
        if (document && document.body && document.documentElement) {
            const theme = isDark ? 'dark' : 'light';
            document.body.dataset.theme = theme;
            document.documentElement.dataset.theme = theme;
            
            // Фон теперь применяется через CSS псевдоэлемент body::before
            const bgColor = theme === 'light' ? '#f5f7fb' : '#050816';
            document.documentElement.style.backgroundColor = bgColor;
        }
    }, [isDark]);

    const toggleTheme = () => {
        setIsDark(!isDark);
    };

    return (
        <ThemeContext.Provider value={{ isDark, toggleTheme }}>
            <div className="app-shell">
                {children}
            </div>
        </ThemeContext.Provider>
    );
}; 