import React from 'react';
import { Button, ButtonGroup } from 'react-bootstrap';

function SubjectToolbar({
    predictionMode,
    setPredictionMode,
    onResetPredictions,
    onClearSavedPredictions
}) {
    return (
        <div className="subject-toolbar">
            <div className="subject-toolbar-left">
                <span className="subject-toolbar-label">Режим предсказания</span>
                <ButtonGroup aria-label="prediction-mode" className="subject-mode-group">
                    <Button
                        variant={predictionMode === 'percent' ? 'secondary' : 'outline-secondary'}
                        size="sm"
                        onClick={() => setPredictionMode('percent')}
                        active={predictionMode === 'percent'}
                        className="subject-mode-btn"
                    >
                        Проценты
                    </Button>
                    <Button
                        variant={predictionMode === 'points' ? 'secondary' : 'outline-secondary'}
                        size="sm"
                        onClick={() => setPredictionMode('points')}
                        active={predictionMode === 'points'}
                        className="subject-mode-btn"
                    >
                        Баллы
                    </Button>
                </ButtonGroup>
            </div>
            <div className="subject-toolbar-right">
                <Button
                    onClick={onResetPredictions}
                    variant="outline-danger"
                    className="quick-reset-btn"
                >
                    Обнулить все предсказания
                </Button>
                <Button
                    onClick={onClearSavedPredictions}
                    variant="outline-primary"
                    className="quick-reset-btn"
                >
                    Сбросить сохранённые предсказания
                </Button>
            </div>
        </div>
    );
}

export default SubjectToolbar;


