import { useState, useEffect } from 'react';

/**
 * Простая утилита для отслеживания, меньше ли ширина окна заданного брейкпоинта.
 * Используется для адаптивного поведения компонентов (например, расписания).
 */
function useResponsiveBreakpoint(maxWidth) {
    const getIsMobile = () =>
        typeof window !== 'undefined' ? window.innerWidth <= maxWidth : false;

    const [isBelowBreakpoint, setIsBelowBreakpoint] = useState(getIsMobile);

    useEffect(() => {
        const handleResize = () => {
            setIsBelowBreakpoint(getIsMobile());
        };

        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, [maxWidth]);

    return isBelowBreakpoint;
}

export default useResponsiveBreakpoint;


