/**
 * Объединяет currentControl и labs из данных журнала предмета.
 */
export function getAllControlPoints(data) {
    if (!data) return [];
    const currentControl = data.currentControl || [];
    const labs = data.labs || [];
    return [...currentControl, ...labs];
}

/**
 * Подсчет итогового фактического рейтинга по данным журнала предмета.
 * Учитывает:
 * - текущий контроль (или курсовые работы),
 * - бонусы (до +15%),
 * - аттестацию (формула 60/40),
 * как на странице предмета.
 */
export function calculateFinalRatingFromJournalData(subjectData, options = {}) {
    if (!subjectData) return 0;

    const { isCourseWork = false } = options;

    let baseRating = 0;

    // Расчет базового рейтинга (текущий контроль или курсовая)
    if (isCourseWork && subjectData.courseWorksOrProjects) {
        let totalWeighted = 0;
        let totalWeight = 0;
        subjectData.courseWorksOrProjects.forEach(item => {
            const w = item.weight || 1;
            const r = item.rating || 0;
            totalWeighted += r * w;
            totalWeight += w;
        });
        baseRating = totalWeight > 0 ? (totalWeighted / totalWeight) : 0;
    } else {
        const allControlPoints = getAllControlPoints(subjectData);
        if (allControlPoints.length > 0) {
            let totalWeighted = 0;
            let totalWeight = 0;
            allControlPoints.forEach(item => {
                const w = item.weight || 1;
                const r = item.rating || 0;
                totalWeighted += r * w;
                totalWeight += w;
            });
            baseRating = totalWeight > 0 ? (totalWeighted / totalWeight) : 0;
        }
    }

    // Расчет бонусного вклада (из фактических данных)
    let bonusContribution = 0;
    if (subjectData.bonuses && subjectData.bonuses.length > 0) {
        let totalBonusWeight = 0;
        subjectData.bonuses.forEach(item => {
            totalBonusWeight += (item.weight || 1);
        });

        subjectData.bonuses.forEach(item => {
            const bonusRating = item.rating || 0;
            const weight = item.weight || 1;
            const weightShare = totalBonusWeight > 0 ? (weight / totalBonusWeight) : 0;
            const itemContribution = (bonusRating / 100) * 15 * weightShare;
            bonusContribution += itemContribution;
        });

        bonusContribution = Math.min(bonusContribution, 15);
    }

    const preAttestationRating = baseRating + bonusContribution;

    // Расчет рейтинга аттестации (из фактических данных)
    let attestationRating = 0;
    if (subjectData.attestation && subjectData.attestation.length > 0) {
        let totalAttestationWeighted = 0;
        let totalAttestationWeight = 0;
        subjectData.attestation.forEach(item => {
            const weight = item.weight || 1;
            const rating = item.rating || 0;
            totalAttestationWeighted += rating * weight;
            totalAttestationWeight += weight;
        });
        attestationRating = totalAttestationWeight > 0 ? (totalAttestationWeighted / totalAttestationWeight) : 0;
    }

    const finalRating = attestationRating > 0
        ? (preAttestationRating * 0.6) + (attestationRating * 0.4)
        : preAttestationRating;

    return finalRating;
}


