import React, { useState, useEffect } from 'react';
import { Container, Card, Badge, Spinner } from 'react-bootstrap';
import { notificationsApi } from '../../api/notificationsApi';
import Loader from '../../shared/components/Loader';
import ErrorAlert from '../../shared/components/ErrorAlert';
import './NotificationsPage.css';

const NotificationsPage = () => {
    const [notifications, setNotifications] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        loadNotifications();
    }, []);

    const loadNotifications = async () => {
        try {
            setLoading(true);
            setError(null);
            const data = await notificationsApi.getUserNotifications();
            setNotifications(data || []);
            
            // Помечаем все непрочитанные уведомления как прочитанные
            if (data && data.length > 0) {
                const unreadNotifications = data.filter(n => !n.IsRead);
                if (unreadNotifications.length > 0) {
                    // Помечаем все непрочитанные уведомления как прочитанные параллельно
                    const markPromises = unreadNotifications.map(notification =>
                        notificationsApi.setNotificationAsRead(notification.Id).catch(err => {
                            console.error(`Error marking notification ${notification.Id} as read:`, err);
                            return null; // Продолжаем даже если одно уведомление не удалось пометить
                        })
                    );
                    
                    await Promise.all(markPromises);
                    
                    // Обновляем локальное состояние
                    const updatedNotifications = data.map(n => ({
                        ...n,
                        IsRead: true
                    }));
                    setNotifications(updatedNotifications);
                }
            }
        } catch (err) {
            console.error('Error loading notifications:', err);
            setError('Не удалось загрузить уведомления. Попробуйте обновить страницу.');
        } finally {
            setLoading(false);
        }
    };

    const formatDate = (dateString) => {
        // Дата приходит в формате "21:07:12 27.11.2025"
        return dateString || '';
    };

    const unreadCount = notifications.filter(n => !n.IsRead).length;

    if (loading) {
        return (
            <Container className="mt-4">
                <Loader />
            </Container>
        );
    }

    if (error) {
        return (
            <Container className="mt-4">
                <ErrorAlert message={error} />
            </Container>
        );
    }

    return (
        <Container className="notifications-page mt-4">
            <div className="notifications-page-header">
                <h2 className="notifications-page-title">Уведомления</h2>
                {unreadCount > 0 && (
                    <Badge bg="primary" className="notifications-page-badge">
                        {unreadCount} непрочитанных
                    </Badge>
                )}
            </div>

            {notifications.length === 0 ? (
                <Card className="card-modern">
                    <Card.Body className="text-center py-5">
                        <p className="text-muted mb-0">Нет уведомлений</p>
                    </Card.Body>
                </Card>
            ) : (
                <div className="notifications-list-page">
                    {notifications.map((notification) => (
                        <Card
                            key={notification.Id}
                            className={`card-modern notification-card ${!notification.IsRead ? 'notification-card-unread' : ''}`}
                        >
                            <Card.Body>
                                <div className="notification-card-header">
                                    <h5 className="notification-card-title">
                                        {notification.Title}
                                    </h5>
                                    {!notification.IsRead && (
                                        <Badge bg="primary" className="notification-card-badge">
                                            Новое
                                        </Badge>
                                    )}
                                </div>
                                <p className="notification-card-message">
                                    {notification.Message}
                                </p>
                                <div className="notification-card-footer">
                                    <span className="notification-card-date">
                                        {formatDate(notification.CreatedAt)}
                                    </span>
                                </div>
                            </Card.Body>
                        </Card>
                    ))}
                </div>
            )}
        </Container>
    );
};

export default NotificationsPage;

